CREATE OR REPLACE FUNCTION public.enforce_min_age()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.birth_date > ((now() at time zone 'Asia/Tokyo')::date - interval '18 years') then
    raise exception '18歳未満は登録できません';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.job_employer_trust_info(p_job_number integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_farmer_id uuid;
begin
  select j.farmer_id into v_farmer_id from public.jobs j where j.job_number = p_job_number and (j.status = 'open' or public.is_job_party(p_job_number));
  if v_farmer_id is null then return json_build_object('ok', false); end if;
  return public.employer_trust_info(v_farmer_id);
end; $function$

CREATE OR REPLACE FUNCTION public.review_window(p_application_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare a public.applications; v_opened timestamptz; v_now timestamptz; v_state text;
begin
  select * into a from public.applications where id=p_application_id;
  if auth.uid() is null or a.id is null or (auth.uid() is distinct from a.farmer_id and auth.uid() is distinct from a.worker_id) then
    return json_build_object('ok',false,'reason','not_entitled');
  end if;
  v_opened := public.app_review_opened_at(a.id); v_now := clock_timestamp();
  v_state := public.review_window_state(v_opened,v_now);
  if a.status in ('applied','rejected','expired','canceled') then v_state := 'not_started'; end if;
  if auth.uid()=a.worker_id and public.app_phase(a) not in ('working','completed') then v_state := 'not_started'; end if;
  return json_build_object('ok',true,'state',v_state,'opens_at',v_opened,
    'closes_at',v_opened+interval '72 hours','server_now',v_now);
end; $function$

CREATE OR REPLACE FUNCTION public.wp_default_nickname()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_base text; v_cand text; v_n int := 1;
begin
  if new.nickname is null or public.wp_nickname_norm(new.nickname) = '' then
    select left(u.email, 2) into v_base from auth.users u where u.id = new.auth_id;
    v_base := coalesce(nullif(btrim(v_base), ''), 'user');
    perform pg_advisory_xact_lock(hashtextextended('wp_nickname:' || public.wp_nickname_norm(v_base), 0));
    v_cand := v_base;
    while exists (select 1 from public.worker_profiles w
                   where w.auth_id <> new.auth_id
                     and public.wp_nickname_norm(w.nickname) = public.wp_nickname_norm(v_cand)) loop
      v_n := v_n + 1; v_cand := v_base || v_n::text;
    end loop;
    new.nickname := v_cand;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.submit_farmer_final_review(p_application_id uuid, p_work_outcome text, p_want_again_choice text, p_traits jsonb DEFAULT '[]'::jsonb, p_favorite boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v json; v_farmer uuid; v_worker uuid;
begin
  if p_work_outcome is null or p_want_again_choice is null
     or not public.review_traits_valid('farmer_to_worker',p_traits)
     or p_work_outcome not in ('completed','partial','not_completed')
     or p_want_again_choice not in ('yes','neutral','no') then
    return json_build_object('ok', false, 'reason', 'bad_input');
  end if;
  select farmer_id, worker_id into v_farmer, v_worker
    from public.applications where id = p_application_id for update;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if auth.uid() is null or v_farmer is distinct from auth.uid() then return json_build_object('ok', false, 'reason', 'not_yours'); end if;

  -- 古いRPCも、完了・メール・お気に入りの副作用を起こす前に期限を検証する。
  begin
    perform public.assert_review_window(p_application_id);
  exception when sqlstate 'P0001' then
    return json_build_object('ok',false,'reason',sqlerrm);
  end;

  -- 完了処理（評価送信は出勤前提＝欠勤は別の道 complete_work(false)。メール失敗は内側で握って続行）
  v := public.complete_work(p_application_id, true);
  if not coalesce((v->>'ok')::boolean, false) then return v; end if;

  insert into public.reviews (application_id, reviewer_id, reviewee_id, direction,
                              work_outcome, want_again_choice, traits,
                              want_again, completed_work)
  values (p_application_id, v_farmer, v_worker, 'farmer_to_worker',
          p_work_outcome, p_want_again_choice,
          coalesce(p_traits, '[]'::jsonb),
          case p_want_again_choice when 'yes' then true when 'no' then false else null end,
          (p_work_outcome = 'completed'));

  if p_want_again_choice = 'yes' and p_favorite then
    insert into public.repeat_roster (farmer_id, worker_id, source_application_id, notify)
    values (v_farmer, v_worker, p_application_id, true)
    on conflict (farmer_id, worker_id) do nothing;
  end if;

  return json_build_object('ok', true, 'favorited', (p_want_again_choice = 'yes' and p_favorite));
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_reviews_phase_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare a public.applications;
begin
  if tg_op='UPDATE' then
    -- 公開コメントの運営による非表示は締切後も可能。入力内容や対象の差し替えは不可。
    if (to_jsonb(new)-'comment_status'-'published_at')=(to_jsonb(old)-'comment_status'-'published_at') then return new; end if;
    if new.application_id is distinct from old.application_id
       or new.reviewer_id is distinct from old.reviewer_id
       or new.reviewee_id is distinct from old.reviewee_id
       or new.direction is distinct from old.direction then
      raise exception using errcode='P0001',message='review_identity_immutable';
    end if;
  end if;
  select * into a from public.applications where id=new.application_id for share;
  if a.id is null then raise exception '評価の応募が存在しません'; end if;
  if (new.direction='farmer_to_worker' and public.app_phase(a)<>'completed')
     or (new.direction='worker_to_farmer' and public.app_phase(a) not in ('working','completed')) then
    raise exception using errcode='P0001',message='review_window_not_started';
  end if;
  perform public.assert_review_window(a.id);
  if tg_op='UPDATE' then raise exception using errcode='P0001',message='review_already_submitted'; end if;
  -- バックデートしたcreated_atやpublished_atで制限をすり抜けさせない。
  new.created_at := clock_timestamp(); new.published_at := null;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.complete_work(p_application_id uuid, p_attended boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_f uuid; v_w uuid; v_job int; v_status text; v_ref text; v_date_start date;
        v_auto boolean; v_att boolean; v_due timestamptz;
begin
  select farmer_id, worker_id, job_number, status, auto_completed, attended
    into v_f, v_w, v_job, v_status, v_auto, v_att
    from public.applications where id = p_application_id;
  if v_f is null then return json_build_object('ok', false, 'reason','not_found'); end if;
  if v_f <> auth.uid() then return json_build_object('ok', false, 'reason','not_yours'); end if;
  if v_status = 'completed' and not (coalesce(v_auto, false) and v_att is null) then
    return json_build_object('ok', true, 'already', true);
  end if;

  if v_status not in ('approved','meeting','interview','contracted','working','completed') then
    return json_build_object('ok', false, 'reason','この応募はまだ承認されていません。承認してから完了を記録してください');
  end if;
  v_due := public.app_work_due_at(p_application_id);
  if v_due is not null and now() < v_due then
    return json_build_object('ok', false, 'reason', 'この仕事はまだ終わっていません。最終作業日（' || to_char(v_due at time zone 'Asia/Tokyo', 'MM/DD HH24:MI') || '）を過ぎてから完了を記録してください');
  end if;

  update public.applications
     set status = 'completed', attended = p_attended,
         work_completed_at = coalesce(work_completed_at, v_due, now())
   where id = p_application_id;
  v_ref := public.job_ref(v_job,'worker');

  if p_attended then
    begin
      perform public.send_user_email(v_w,
        '[chitose-bank] お疲れさまでした：求人 #' || v_job,
        '■ ' || v_ref || E'\n\n' ||
        '作業お疲れさまでした。評価は最終作業の終了から72時間以内に送信できます。公開は72時間後です。' || E'\n\n' ||
        'https://chitose-bank.com/#/profile/worker/approved');
    exception when others then null; end;
  else
    insert into public.notifications (farmer_id, type, message)
    values (v_w, 'no_show_recorded',
            '欠勤が記録されました：求人 #' || v_job || '　心当たりがない場合は72時間以内に異議申立ができます');
    begin
      perform public.send_user_email(v_w,
        '[chitose-bank] 欠勤が記録されました：求人 #' || v_job,
        '■ ' || v_ref || E'\n\n' ||
        '農家により欠勤が記録されました。' || E'\n' ||
        '心当たりがない場合は、72時間以内にアプリから異議申立ができます。' || E'\n' ||
        '（承認済みタブ → 該当の仕事 → 異議申立）' || E'\n\n' ||
        'https://chitose-bank.com');
    exception when others then null; end;
    perform public.notify_admins('no_show_recorded', '欠勤記録：求人 #' || v_job || '（異議窓72時間）');
  end if;
  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.moderate_review_comment(p_review_id uuid, p_approve boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  -- 即時公開になったので、承認ではなく「非表示にする／公開に戻す」の操作になった
  update public.reviews
     set comment_status = case when p_approve then 'approved' else 'rejected' end
   where id = p_review_id
     and nullif(btrim(coalesce(public_comment,'')),'') is not null;
  if not found then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  return json_build_object('ok', true, 'status', case when p_approve then 'approved' else 'rejected' end);
end;
$function$

CREATE OR REPLACE FUNCTION public.my_worker_trust_stats()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_joined timestamptz; v_verified timestamptz;
  v_reviewed int; v_want int; v_completed int; v_hours int;
begin
  if auth.uid() is null then
    return json_build_object('ok', false, 'reason', 'not_signed_in');
  end if;

  select created_at into v_joined from auth.users where id = auth.uid();
  select created_at into v_verified from public.account_holders where auth_id = auth.uid();

  select count(*), count(*) filter (where want_again)
    into v_reviewed, v_want
    from public.reviews
   where reviewee_id = auth.uid()
     and direction = 'farmer_to_worker'
     and want_again is not null
     and public.app_review_published(application_id);

  select count(*) into v_completed
    from public.applications
   where worker_id = auth.uid() and status = 'completed' and attended is distinct from false;

  select (coalesce(sum(public.app_accrued_minutes(a.id)), 0) / 60)::int
    into v_hours
    from public.applications a
    join public.jobs j on j.job_number = a.job_number
   where a.worker_id = auth.uid() and a.status in ('working','completed') and a.attended is distinct from false;

  return json_build_object(
    'ok', true, 'joined_at', v_joined, 'verified_at', v_verified,
    'reviewed_count', coalesce(v_reviewed, 0), 'want_again_count', coalesce(v_want, 0),
    'completed_count', coalesce(v_completed, 0), 'total_hours', coalesce(v_hours, 0));
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_withdrawal(p_auth_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  d jsonb := '{}'::jsonb;
  n int;
begin
  if v_caller is not null and not exists (select 1 from public.app_admins a where a.auth_id = v_caller) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  if exists (select 1 from public.app_admins a where a.auth_id = p_auth_id) then
    return json_build_object('ok', false, 'reason', 'target_is_admin');
  end if;
  if not exists (select 1 from auth.users where id = p_auth_id) then
    return json_build_object('ok', false, 'reason', 'user_not_found');
  end if;

  -- (a) 本人の届出情報・行動の好み＝行ごと削除（対象はコメントの列挙と1対1・汎用化しない）
  delete from public.worker_profiles      where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('worker_profiles', n);
  delete from public.employer_profiles    where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('employer_profiles', n);
  delete from public.consignment_profiles where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('consignment_profiles', n);
  delete from public.account_holders      where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('account_holders', n);
  delete from public.emergency_contacts   where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('emergency_contacts', n);
  delete from public.push_subscriptions   where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('push_subscriptions', n);
  delete from public.saved_jobs           where worker_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('saved_jobs', n);
  delete from public.worker_profile_view_counts where worker_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('worker_profile_view_counts', n);
  delete from public.repeat_roster        where farmer_id = p_auth_id or worker_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('repeat_roster', n);
  delete from public.pending_applications where worker_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('pending_applications', n);
  delete from public.chat_reads           where reader_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('chat_reads', n);
  delete from public.notifications        where farmer_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('notifications', n);
  delete from public.page_events          where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('page_events', n);
  delete from public.auth_logs            where farmer_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('auth_logs', n);
  delete from public.farmers              where auth_id  = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('farmers', n);
  delete from public.records              where farmer_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('records', n);
  delete from public.user_onboarding_survey where auth_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('user_onboarding_survey', n);
  delete from public.feedback             where reporter_id = p_auth_id; get diagnostics n = row_count; d := d || jsonb_build_object('feedback', n);

  -- 退会農家の公開中/審査中の求人を掲載終了に（2026-08-07 X4）：行は消さず応募受付だけ止める。
  -- draftは公開されていないので対象外。過去求人の証跡（応募・はたらいた記録）は残す。
  update public.jobs set status = 'closed' where farmer_id = p_auth_id and status in ('open','pending');
  get diagnostics n = row_count; d := d || jsonb_build_object('jobs_closed', n);

  -- (b) メールの削除＝匿名化（行は残す・FKと証跡は無傷）
  update auth.users set
    email = 'withdrawn+' || p_auth_id || '@withdrawn.invalid',
    encrypted_password = '',
    raw_user_meta_data = '{}'::jsonb,
    phone = null,
    email_change = '',
    email_change_token_new = '',
    confirmation_token = '',
    recovery_token = '',
    banned_until = 'infinity'
  where id = p_auth_id;
  delete from auth.identities      where user_id = p_auth_id;
  delete from auth.sessions        where user_id = p_auth_id;
  delete from auth.one_time_tokens where user_id = p_auth_id;
  delete from auth.mfa_factors     where user_id = p_auth_id;

  -- (c) 退会処理の記録（冪等・2026-08-07 W4修正）：申請行があれば processed_at を刻む／無ければ1行作る。
  if exists (select 1 from public.withdrawal_requests where auth_id = p_auth_id) then
    update public.withdrawal_requests set processed_at = coalesce(processed_at, now())
     where auth_id = p_auth_id;
  else
    insert into public.withdrawal_requests (auth_id, requested_at, processed_at)
    values (p_auth_id, now(), now());
  end if;

  return json_build_object('ok', true, 'deleted', d,
    'note', 'アイコン画像（avatars/' || p_auth_id || '/）はストレージAPIから手動で削除すること（SQL削除はプラットフォームで禁止）。');
end $function$

CREATE OR REPLACE FUNCTION public.record_my_attendance_once(p_owner uuid, p_event_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_input jsonb;
  v_previous jsonb;
  v_row public.attendance_events%rowtype;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_event_id is null or jsonb_typeof(p_input) is distinct from 'object'
    or not (p_input ?& array['application_id','kind'])
    or p_input - array['application_id','kind','reason','work_date','detail'] <> '{}'::jsonb
    or jsonb_typeof(p_input->'application_id') is distinct from 'string'
    or jsonb_typeof(p_input->'kind') is distinct from 'string' or octet_length(p_input::text)>65536
    or exists(select 1 from jsonb_each(p_input) where key in ('reason','detail','work_date') and value<>'null'::jsonb and jsonb_typeof(value)<>'string') then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  v_input:=jsonb_build_object('application_id',(p_input->>'application_id')::uuid,'kind',p_input->>'kind',
    'reason',p_input->>'reason','work_date',(p_input->>'work_date')::date,'detail',p_input->>'detail');
  perform pg_advisory_xact_lock(hashtextextended('attendance:'||p_event_id::text,0));
  select * into v_row from public.attendance_events where id=p_event_id;
  if found then
    select jsonb_object_agg(key,value) into v_previous from jsonb_each(to_jsonb(v_row)) where key=any(array['application_id','kind','reason','work_date','detail']);
    if v_row.actor_id is distinct from v_uid or v_previous is distinct from v_input then return jsonb_build_object('ok',false,'reason','request_mismatch'); end if;
    return jsonb_build_object('ok',true,'row',to_jsonb(v_row),'replayed',true);
  end if;
  begin
    insert into public.attendance_events(id,application_id,actor_id,kind,reason,work_date,detail)
      values(p_event_id,(v_input->>'application_id')::uuid,v_uid,v_input->>'kind',v_input->>'reason',(v_input->>'work_date')::date,v_input->>'detail')
      returning * into v_row;
    if v_row.id is null then raise exception 'ATTENDANCE_NOT_SAVED'; end if;
    return jsonb_build_object('ok',true,'row',to_jsonb(v_row),'replayed',false);
  exception when unique_violation then
    -- Another permitted insertion path may not take this advisory lock.
    select * into v_row from public.attendance_events where id=p_event_id and actor_id=v_uid;
    select jsonb_object_agg(key,value) into v_previous from jsonb_each(to_jsonb(v_row)) where key=any(array['application_id','kind','reason','work_date','detail']);
    if v_row.id is not null and v_previous=v_input then return jsonb_build_object('ok',true,'row',to_jsonb(v_row),'replayed',true); end if;
    return jsonb_build_object('ok',false,'reason','request_mismatch');
  when others then
    return jsonb_build_object('ok',false,'reason','save_rejected','code',sqlstate);
  end;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then
  return jsonb_build_object('ok',false,'reason','invalid_input');
end $function$

CREATE OR REPLACE FUNCTION public.app_error_report_to_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin uuid; v_msg text; v_sig text; v_mark text; v_device text; v_page text;
  v_bot boolean := coalesce(new.user_agent,'') ~* '(^|[^a-z0-9_-])googlebot(-[a-z]+)?(/|[[:space:];)]|$)';
begin
  begin
    if lower(coalesce(new.message,'')) like any (array[
      '%importing a module script failed%','%dynamically imported module%','%loading chunk%','%loading css chunk%'
    ]) then return new; end if;
    select id into v_admin from auth.users where email = 't5fki6643qty@gmail.com' limit 1;
    if v_admin is null then return new; end if;
    -- 種類の署名＝フロント errorSignature（lib/errorCatalog）と同じ規則（uuid→{id}・4桁以上の数字→{n}）
    v_sig := coalesce(new.component,'') || '|' || coalesce(new.source,'') || '|' ||
             regexp_replace(regexp_replace(left(coalesce(new.message,'(none)'),200),
               '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '{id}', 'gi'),
               '[0-9]{4,}', '{n}', 'g');
    -- 自動巡回の通知で一般利用者の同型エラーを間引かない。
    if v_bot then v_sig := 'Googlebot|' || v_sig; end if;
    v_mark := '#err:' || left(md5(v_sig), 8);
    if exists (select 1 from public.admin_messages m
                where m.user_id = v_admin and m.from_admin
                  and m.created_at > now() - interval '1 hour'
                  and m.body like '%' || v_mark || '%') then return new; end if;
    v_device := case when v_bot then 'Googlebot（自動巡回）'
                     when new.user_agent is null then '不明'
                     when new.user_agent ~* 'iphone|ipad' then 'iPhone/iPad'
                     when new.user_agent ~* 'android' then 'Android' else 'PC等' end;
    v_page := coalesce(nullif(new.page,''), nullif(regexp_replace(coalesce(new.url,''), '^[^#]*#', ''), ''), '-');
    v_msg := '【エラーの報告】' || to_char(coalesce(new.created_at, now()) at time zone 'Asia/Tokyo', 'MM/DD HH24:MI') || E'\n' ||
             '発生場所：' || coalesce(nullif(new.component,''),'-') || '／' || coalesce(nullif(new.source,''),'-') ||
             case when coalesce(new.error_code,'') <> '' then '／コード ' || new.error_code else '' end || E'\n' ||
             'ページ：' || v_page || '　端末・アクセス元：' || v_device ||
             '　利用者：' || case when v_bot then '自動巡回（Googlebot）' when new.user_id is null then '未ログイン' else 'ログイン中' end || E'\n' ||
             left(coalesce(new.message,'(メッセージなし)'), 300) || E'\n\n' ||
             '詳しくは https://www.chitose-bank.com/#/admin/system' || E'\n' || v_mark;
    insert into public.admin_messages (user_id, from_admin, body) values (v_admin, true, v_msg);
  exception when others then null;  -- 報告は補助機能＝失敗しても本体（エラーの記録）を止めない
  end;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_insurance(p_application_id uuid, p_items text[] DEFAULT NULL::text[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid; v_farmer uuid; v_worker uuid; v_job int; v_prepared timestamptz;
  v_labels text; v_body text;
begin
  v_caller := auth.uid();
  if v_caller is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  select farmer_id, worker_id, job_number, insurance_prepared_at
    into v_farmer, v_worker, v_job, v_prepared
    from public.applications where id = p_application_id;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_farmer <> v_caller then return json_build_object('ok', false, 'reason', 'not_yours'); end if;
  if v_prepared is not null then return json_build_object('ok', true, 'already', true); end if;

  update public.applications set insurance_prepared_at = now() where id = p_application_id;

  -- 報告された保険の名前。固定の対応表にあるキーだけを日本語に直す（順番も表のとおり）。
  -- 「これから準備する(considering)」は未加入なので対象外＝報告の名前には出さない。
  select string_agg(m.label, chr(10) order by m.ord) into v_labels
  from (values
    ('day_accident',    1, '・1日単位の傷害保険'),
    ('annual_accident', 2, '・年間の傷害保険'),
    ('rosai',           3, '・労災保険'),
    ('facility',        4, '・施設・賠償責任保険'),
    ('vehicle',         5, '・車両保険')
  ) as m(k, ord, label)
  where m.k = any(coalesce(p_items, '{}'::text[]));

  v_body := '作業中のケガに備える保険の準備ができました。'
    || coalesce(chr(10) || v_labels, '')
    || chr(10) || chr(10)
    || '内容（種類・補償の範囲）が気になるときは、このチャットで気軽に聞いてください。';

  -- チャットへ投函（この関数は SECURITY DEFINER＝messages のRLSは適用されない）。
  -- 相手へのお知らせ・プッシュ・メールは trg_notify_message が担う
  insert into public.messages (application_id, sender_id, body)
  values (p_application_id, v_farmer, v_body);

  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.notify_admin_on_user_dm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  if new.from_admin then return new; end if;
  if exists (select 1 from app_admins a where a.auth_id = new.user_id) then return new; end if;
  v_name := coalesce(nullif(btrim(public.resolve_actor_name(new.user_id)), ''), '利用者');
  insert into public.notifications (farmer_id, type, message)
  select a.auth_id, 'admin_dm_inbound', '運営チャットに ' || v_name || ' さんからメッセージが届きました。'
    from public.app_admins a;
  perform public.send_admin_email(
    '[chitose-bank] 運営チャットに新しいメッセージ（' || v_name || ' さん）',
    v_name || ' さんから運営チャットにメッセージが届きました。' || chr(10) || chr(10) ||
    '確認・返信はこちら：' || chr(10) ||
    'https://chitose-bank.com/#/chat/admin/' || new.user_id::text);
  return new;
exception when others then return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.consignment_summary(p_deal_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_area numeric; v_hours numeric; v_boxes int; v_days int; v_workers int;
begin
  if not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  select coalesce(area_a, nullif(btrim(spec->>'area_a'),'')::numeric) into v_area
    from public.consignment_deals where id = p_deal_id;
  select coalesce(sum(hours),0), coalesce(sum(yield_boxes),0), count(distinct work_date), coalesce(sum(workers),0)
    into v_hours, v_boxes, v_days, v_workers
    from public.consignment_progress where deal_id = p_deal_id;
  return json_build_object('ok', true,
    'total_hours', v_hours, 'total_boxes', v_boxes, 'work_days', v_days, 'total_workers', v_workers,
    'area_a', v_area,
    'hours_per_10a', case when v_area is not null and v_area > 0 then round(v_hours * 10 / v_area, 1) else null end);
end; $function$

CREATE OR REPLACE FUNCTION public.wp_review_dedupe()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_pend_qa jsonb; v_appr_qa jsonb;
begin
  -- 1. 空白のみの審査依頼は無い
  if new.pr_pending is not null and btrim(new.pr_pending) = '' then
    new.pr_pending := null;
  end if;

  -- 2. 承認済み本文と同一なら審査に入れない
  if new.pr_pending is not null
     and btrim(new.pr_pending) = btrim(coalesce(new.pr, '')) then
    new.pr_pending := null;
  end if;

  -- 3. Q&A：正規化した (質問, 回答) の集合が承認済みと同一なら審査に入れない
  if new.pr_qa_pending is not null then
    select coalesce(jsonb_agg(x order by x), '[]'::jsonb) into v_pend_qa
      from (select distinct jsonb_build_array(
                     coalesce(e->>'q', e->>'question', ''),
                     btrim(coalesce(e->>'a', e->>'answer', ''))) as x
              from jsonb_array_elements(new.pr_qa_pending) e) s;
    select coalesce(jsonb_agg(x order by x), '[]'::jsonb) into v_appr_qa
      from (select distinct jsonb_build_array(
                     coalesce(e->>'q', e->>'question', ''),
                     btrim(coalesce(e->>'a', e->>'answer', ''))) as x
              from jsonb_array_elements(coalesce(new.pr_qa, '[]'::jsonb)) e) s;
    if v_pend_qa = v_appr_qa then
      new.pr_qa_pending := null;
    end if;
  end if;

  -- 4. 審査に出すものが無ければ、申請時刻と修正依頼の印も残さない
  if new.pr_pending is null and new.pr_qa_pending is null then
    new.pr_submitted_at := null;
    new.pr_revision_targets := null;
  end if;

  -- 5. 中身の変わらない再提出で申請時刻を進めない（48時間の自動公開が後ろにずれない）
  --    new.pr_submitted_at is not null が必須：修正依頼は pending を残したまま申請時刻を
  --    null にして審査の列から外す＝その null 化を打ち消さない
  if tg_op = 'UPDATE'
     and old.pr_submitted_at is not null
     and new.pr_submitted_at is not null
     and (new.pr_pending is not null or new.pr_qa_pending is not null)
     and coalesce(btrim(new.pr_pending), '') = coalesce(btrim(old.pr_pending), '')
     and coalesce(new.pr_qa_pending, '[]'::jsonb) = coalesce(old.pr_qa_pending, '[]'::jsonb) then
    new.pr_submitted_at := old.pr_submitted_at;
  end if;

  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.profile_text_ng(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p is null or btrim(p) = '' then return null; end if;
  if p ~ '0\d{1,4}[-‐−ー\s]?\d{1,4}[-‐−ー\s]?\d{3,4}' then
    return '電話番号は記載できません（連絡はサイト内でお願いします）';
  end if;
  if p ~* '[a-z0-9._%+-]+@[a-z0-9.-]+' then
    return 'メールアドレスは記載できません';
  end if;
  if p ~* 'https?://|www\.' then
    return 'URLは記載できません';
  end if;
  return null;
end; $function$

CREATE OR REPLACE FUNCTION public.wp_z_publish_texts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_folded boolean := false; v_ng text; v_e jsonb; v_qa_text text;
begin
  if new.pr_pending is not null then
    new.pr := nullif(btrim(new.pr_pending), '');
    new.pr_pending := null;
    v_folded := true;
  end if;
  if new.pr_qa_pending is not null then
    new.pr_qa := new.pr_qa_pending;
    new.pr_qa_pending := null;
    v_folded := true;
  end if;
  if v_folded then
    new.pr_submitted_at := null;
    new.pr_revision_targets := null;
  end if;

  if (tg_op = 'INSERT' and new.pr is not null)
     or (tg_op = 'UPDATE' and new.pr is distinct from old.pr) then
    v_ng := public.profile_text_ng(new.pr);
    if v_ng is not null then raise exception '自己紹介：%', v_ng; end if;
  end if;
  if (tg_op = 'INSERT' and new.pr_qa is not null)
     or (tg_op = 'UPDATE' and new.pr_qa is distinct from old.pr_qa) then
    for v_e in select value from jsonb_array_elements(coalesce(new.pr_qa, '[]'::jsonb))
    loop
      v_ng := public.profile_text_ng(coalesce(v_e->>'q', v_e->>'question'));
      if v_ng is not null then raise exception 'Q&Aの質問：%', v_ng; end if;
      v_ng := public.profile_text_ng(coalesce(v_e->>'a', v_e->>'answer'));
      if v_ng is not null then raise exception 'Q&Aの回答：%', v_ng; end if;
    end loop;
  end if;

  if v_folded and not exists (select 1 from public.app_admins a where a.auth_id = new.auth_id) then
    begin
      select string_agg('Q：' || coalesce(e->>'q', e->>'question','？') || E'\n' ||
                        'A：' || coalesce(e->>'a', e->>'answer','（未回答）'), E'\n\n')
        into v_qa_text
        from jsonb_array_elements(coalesce(new.pr_qa, '[]'::jsonb)) e;
      perform public.send_admin_email(
        '[公開・事後確認] 自己紹介が公開されました：' || coalesce(nullif(new.nickname,''),'（名前未設定）'),
        '働き手の自由記述が公開されました（保存＝即公開・2026-08-14承認プロセス廃止）。' || E'\n' ||
        '電話番号・メール・URLは保存時に自動拒否済み。' || E'\n\n' ||
        '■ 自己紹介：' || E'\n' || coalesce(new.pr, '（なし）') || E'\n\n' ||
        '■ Q&A：' || E'\n' || coalesce(v_qa_text, '（なし）') || E'\n\n' ||
        '公開後の確認：個人の特定・不適切な表現があれば、管理画面アカウント面の運営DMで修正を依頼するか、直接対処してください。');
    exception when others then null;
    end;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.ep_z_publish_texts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  tp jsonb; v_folded boolean := false; v_ng text;
  j_new jsonb; j_old jsonb; v_col text; v_label text;
begin
  tp := coalesce(new.texts_pending, '{}'::jsonb);
  if tp <> '{}'::jsonb then
    new.owner_comment            := coalesce(tp->>'owner_comment', new.owner_comment);
    new.intro_path               := coalesce(tp->>'intro_path', new.intro_path);
    new.intro_joy                := coalesce(tp->>'intro_joy', new.intro_joy);
    new.intro_crops              := coalesce(tp->>'intro_crops', new.intro_crops);
    new.intro_atmosphere         := coalesce(tp->>'intro_atmosphere', new.intro_atmosphere);
    new.intro_message            := coalesce(tp->>'intro_message', new.intro_message);
    new.unique_point             := coalesce(tp->>'unique_point', new.unique_point);
    new.always_do                := coalesce(tp->>'always_do', new.always_do);
    new.break_style              := coalesce(tp->>'break_style', new.break_style);
    new.transport_area           := coalesce(tp->>'transport_area', new.transport_area);
    new.commute_allowance_detail := coalesce(tp->>'commute_allowance_detail', new.commute_allowance_detail);
    new.supplies_cap             := coalesce(tp->>'supplies_cap', new.supplies_cap);
    new.raise_detail             := coalesce(tp->>'raise_detail', new.raise_detail);
    new.bonus_detail             := coalesce(tp->>'bonus_detail', new.bonus_detail);
    new.severance_detail         := coalesce(tp->>'severance_detail', new.severance_detail);
    new.texts_pending := '{}'::jsonb;
    new.texts_submitted_at := null;
    new.texts_revision_requested_at := null;
    v_folded := true;
  end if;

  j_new := to_jsonb(new);
  j_old := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  for v_col, v_label in
    select * from (values
      ('owner_comment','代表より'), ('intro_path','就農するまで'), ('intro_joy','いま楽しいこと'),
      ('intro_crops','どんな作物を、どんな想いで'), ('intro_atmosphere','職場の雰囲気'),
      ('intro_message','初めての人へのメッセージ'), ('unique_point','畑・農園のユニークなところ'),
      ('always_do','いつもしていること'), ('break_style','休憩とお茶'), ('transport_area','送迎エリア'),
      ('commute_allowance_detail','通勤手当の内容'), ('supplies_cap','持ち物の上限設定'),
      ('raise_detail','昇給の内容'), ('bonus_detail','賞与の内容'), ('severance_detail','退職手当の内容'), ('pr','農園紹介')
    ) t(col, label)
  loop
    if (j_new->>v_col) is distinct from (j_old->>v_col) then
      v_ng := public.profile_text_ng(j_new->>v_col);
      if v_ng is not null then raise exception '%：%', v_label, v_ng; end if;
    end if;
  end loop;

  if v_folded and not exists (select 1 from public.app_admins a where a.auth_id = new.auth_id) then
    begin
      perform public.send_admin_email(
        '[公開・事後確認] 農家プロフィールの自由記述が公開されました：' || coalesce(nullif(new.nickname,''),'（名前未設定）'),
        '農家（雇い手）の自由記述が公開されました（保存＝即公開・2026-08-14承認プロセス廃止）。' || E'\n' ||
        '電話番号・メール・URLは保存時に自動拒否済み。' || E'\n\n' ||
        '公開された内容：' || tp::text || E'\n\n' ||
        '公開後の確認：個人の特定・不適切な表現があれば、管理画面アカウント面の運営DMで修正を依頼するか、直接対処してください。');
    exception when others then null;
    end;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.confirm_worker_terms(p_owner uuid, p_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_app public.applications%rowtype;
  v_message uuid;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  select * into v_app from public.applications where id=p_application_id for update;
  if not found or v_app.worker_id is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_party'); end if;
  if public.is_account_moderated(v_uid) then return jsonb_build_object('ok',false,'reason','moderated'); end if;
  -- Includes confirmations stamped at application creation. Never send an
  -- unsolicited historical message or reset a frozen existing contract.
  if v_app.terms_confirmed_worker_at is not null then
    return jsonb_build_object('ok',true,'owner',v_uid,'application_id',v_app.id,'worker_confirmed',true,
      'farmer_confirmed',v_app.terms_confirmed_farmer_at is not null,'already',true);
  end if;
  -- Same closed-state restriction as the existing message INSERT RLS.
  if v_app.status in ('rejected','expired','canceled','completed') then return jsonb_build_object('ok',false,'reason','closed'); end if;
  update public.applications set terms_confirmed_worker_at=now() where id=v_app.id returning * into v_app;
  if v_app.terms_confirmed_worker_at is null then raise exception 'CONFIRMATION_NOT_SAVED'; end if;
  if v_app.terms_confirmed_farmer_at is not null then
    update public.applications a set terms_snapshot=coalesce(a.terms_snapshot,
      (select to_jsonb(j)-'lat'-'lng' from public.jobs j where j.job_number=v_app.job_number)
      ||jsonb_build_object('snapshot_at',now())) where a.id=v_app.id returning * into v_app;
    if v_app.terms_snapshot is null then raise exception 'TERMS_SNAPSHOT_NOT_SAVED'; end if;
  end if;
  insert into public.messages(application_id,sender_id,body)
    values(v_app.id,v_uid,'✓ 求人内容を確認しました。よろしくお願いします。') returning id into v_message;
  if v_message is null then raise exception 'CONFIRMATION_MESSAGE_NOT_SAVED'; end if;
  return jsonb_build_object('ok',true,'owner',v_uid,'application_id',v_app.id,'worker_confirmed',true,
    'farmer_confirmed',v_app.terms_confirmed_farmer_at is not null,'message_id',v_message,'already',false);
exception when others then
  -- PostgreSQL rolls back the update, snapshot, message and transactional
  -- notification side effects before returning this definite rejection.
  return jsonb_build_object('ok',false,'reason','save_rejected','code',sqlstate);
end $function$

CREATE OR REPLACE FUNCTION public.worker_want_again_count(p_worker_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  if auth.uid() is null then
    return json_build_object('ok', false, 'reason', 'not_entitled');
  end if;
  if auth.uid() <> p_worker_id and not exists (
    select 1 from public.applications a
    where a.worker_id = p_worker_id and a.farmer_id = auth.uid()
  ) then
    return json_build_object('ok', false, 'reason', 'not_entitled');
  end if;

  select count(*) into v_count from public.reviews
    where reviewee_id = p_worker_id and direction = 'farmer_to_worker' and want_again = true
      and public.app_review_published(application_id);

  return json_build_object('ok', true, 'want_again_count', v_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_consignment_aux(p_owner uuid, p_operation text, p_id uuid, p_expected jsonb, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_field public.consignment_fields%rowtype;
  v_profile public.consignment_profiles%rowtype;
  v_deal public.consignment_deals%rowtype;
  v_progress public.consignment_progress%rowtype;
  v_row jsonb;
  v_base jsonb;
  v_action text;
  v_from text;
  v_to text;
  v_date date;
  v_found boolean;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if not exists(select 1 from public.app_admins where auth_id=v_uid) then return jsonb_build_object('ok',false,'reason','forbidden'); end if;
  if p_id is null or p_operation is null or p_operation not in ('field_save','field_delete','lend','terms','advance','progress')
    or jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>262144 then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('consignment-aux:'||p_id::text,0));
  if p_operation in ('field_save','field_delete') then
    select * into v_field from public.consignment_fields where id=p_id for update;
    v_found:=found;
    if v_found and v_field.auth_id is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_owner'); end if;
    v_base:=case when v_found then jsonb_build_object('name',v_field.name,'region',v_field.region,'area_a',v_field.area_a,'data',v_field.data,'updated_at',v_field.updated_at) else null end;
    if p_expected is not null then p_expected:=p_expected||jsonb_build_object('updated_at',(p_expected->>'updated_at')::timestamptz); end if;
    if p_operation='field_delete' then
      if p_input<>'{}'::jsonb then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
      if v_found and v_base is distinct from p_expected then return jsonb_build_object('ok',false,'reason','conflict'); end if;
      if v_found then delete from public.consignment_fields where id=p_id returning * into v_field; if not found then raise exception 'FIELD_DELETE_NOT_SAVED'; end if; end if;
      v_row:='null'::jsonb;
    else
      if not(p_input ?& array['name','region','area_a','data']) or p_input-array['name','region','area_a','data']<>'{}'::jsonb
        or exists(select 1 from jsonb_each(p_input-array['data']) where jsonb_typeof(value) is distinct from 'string')
        or nullif(btrim(p_input->>'name'),'') is null or jsonb_typeof(p_input->'data') is distinct from 'object' then
        return jsonb_build_object('ok',false,'reason','invalid_input');
      end if;
      if not(v_found and v_base-'updated_at'=p_input) then
        if v_base is distinct from p_expected then return jsonb_build_object('ok',false,'reason','conflict'); end if;
        if v_found then
          update public.consignment_fields set name=p_input->>'name',region=p_input->>'region',area_a=p_input->>'area_a',data=p_input->'data',updated_at=clock_timestamp()
            where id=p_id and auth_id=v_uid returning * into v_field;
        else
          insert into public.consignment_fields(id,auth_id,name,region,area_a,data) values(p_id,v_uid,p_input->>'name',p_input->>'region',p_input->>'area_a',p_input->'data') returning * into v_field;
        end if;
        if v_field.id is null then raise exception 'FIELD_NOT_SAVED'; end if;
      end if;
      v_row:=to_jsonb(v_field);
    end if;
  elsif p_operation in ('lend','terms') then
    if p_id is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_owner'); end if;
    -- The existing consignor/profile writers also lock this owner or row.
    perform pg_advisory_xact_lock(hashtextextended('consignor:'||v_uid::text,0));
    select * into v_profile from public.consignment_profiles where auth_id=v_uid for update;
    v_found:=found;
    if p_operation='lend' then
      if p_input - 'items'<>'{}'::jsonb or jsonb_typeof(p_input->'items') is distinct from 'array'
        or jsonb_array_length(p_input->'items')>500 or exists(select 1 from jsonb_array_elements(p_input->'items') x
        where jsonb_typeof(x)<>'object' or x-array['k','n']<>'{}'::jsonb or jsonb_typeof(x->'k') is distinct from 'string' or jsonb_typeof(x->'n') is distinct from 'string' or nullif(btrim(x->>'n'),'') is null) then
        return jsonb_build_object('ok',false,'reason','invalid_input');
      end if;
      if coalesce(v_profile.consignor_data->'cmn_lend_items','null'::jsonb) is distinct from p_input->'items' then
        if coalesce(v_profile.consignor_data->'cmn_lend_items','null'::jsonb) is distinct from coalesce(p_expected,'null'::jsonb) then return jsonb_build_object('ok',false,'reason','conflict'); end if;
        if v_found then update public.consignment_profiles set consignor_data=jsonb_set(consignor_data,'{cmn_lend_items}',p_input->'items'),updated_at=clock_timestamp() where auth_id=v_uid returning * into v_profile;
        else insert into public.consignment_profiles(auth_id,consignor_data) values(v_uid,jsonb_build_object('cmn_lend_items',p_input->'items')) returning * into v_profile; end if;
      end if;
    else
      if p_input is distinct from jsonb_build_object('version','consignment-terms-v1-2026-08') then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
      if not coalesce(v_profile.consignment_terms_consent and v_profile.consignment_terms_consent_version=p_input->>'version',false) then
        insert into public.consignment_profiles(auth_id,consignment_terms_consent,consignment_terms_consent_at,consignment_terms_consent_version,consignment_terms_consent_user_id)
        values(v_uid,true,clock_timestamp(),p_input->>'version',v_uid) on conflict(auth_id) do update set consignment_terms_consent=true,
          consignment_terms_consent_at=excluded.consignment_terms_consent_at,consignment_terms_consent_version=excluded.consignment_terms_consent_version,
          consignment_terms_consent_user_id=v_uid,updated_at=clock_timestamp() returning * into v_profile;
      end if;
    end if;
    if v_profile.auth_id is null then raise exception 'PROFILE_NOT_SAVED'; end if;
    v_row:=to_jsonb(v_profile);
  elsif p_operation='progress' then
    if not(p_input ?& array['deal_id','work_date','hours','workers','yield_boxes','note']) or p_input-array['deal_id','work_date','hours','workers','yield_boxes','note']<>'{}'::jsonb
      or jsonb_typeof(p_input->'note') is distinct from 'string' or p_input->>'work_date' is null or not isfinite((p_input->>'work_date')::date)
      or exists(select 1 from jsonb_each(p_input) where key in ('hours','workers','yield_boxes') and value<>'null'::jsonb and (jsonb_typeof(value)<>'number' or (value::text)::numeric<0))
      or (p_input->>'workers')::numeric is distinct from trunc((p_input->>'workers')::numeric)
      or (p_input->>'yield_boxes')::numeric is distinct from trunc((p_input->>'yield_boxes')::numeric) then
      return jsonb_build_object('ok',false,'reason','invalid_input');
    end if;
    select * into v_deal from public.consignment_deals where id=(p_input->>'deal_id')::uuid for update;
    if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if;
    select * into v_progress from public.consignment_progress where id=p_id;
    v_found:=found;
    if not v_found then
      insert into public.consignment_progress(id,deal_id,work_date,hours,workers,yield_boxes,note) values(p_id,v_deal.id,(p_input->>'work_date')::date,
        (p_input->>'hours')::numeric,(p_input->>'workers')::integer,(p_input->>'yield_boxes')::integer,p_input->>'note') returning * into v_progress;
      if v_progress.id is null then raise exception 'PROGRESS_NOT_SAVED'; end if;
    end if;
    if to_jsonb(v_progress)-array['id','created_at'] is distinct from p_input then
      if not v_found then raise exception 'PROGRESS_NOT_CONFIRMED'; end if;
      return jsonb_build_object('ok',false,'reason','conflict');
    end if;
    v_row:=to_jsonb(v_progress);
  else
    if not(p_input ?& array['action','date','note']) or p_input-array['action','date','note']<>'{}'::jsonb
      or jsonb_typeof(p_input->'note') is distinct from 'string' then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
    v_action:=p_input->>'action';v_date:=(p_input->>'date')::date;
    if v_action is null or v_action not in ('agree','deposit','start','inspect','pay','complete') or v_date is null or not isfinite(v_date) then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
    select * into v_deal from public.consignment_deals where id=p_id for update;
    if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if;
    v_from:=case v_action when 'agree' then 'draft' when 'deposit' then 'agreed' when 'start' then 'agreed' when 'inspect' then 'working' when 'pay' then 'inspected' when 'complete' then 'paid' end;
    v_to:=case v_action when 'agree' then 'agreed' when 'deposit' then 'agreed' when 'start' then 'working' when 'inspect' then 'inspected' when 'pay' then 'paid' when 'complete' then 'done' end;
    if not coalesce(v_deal.status=v_to and case v_action when 'deposit' then v_deal.spec->>'deposit_received_at'=v_date::text
      when 'inspect' then v_deal.inspected_at=v_date and coalesce(v_deal.notes,'')=p_input->>'note'
      when 'pay' then v_deal.paid_at=v_date when 'complete' then v_deal.spec->>'reflection'=p_input->>'note' else true end,false) then
      if v_deal.status is distinct from v_from or v_deal.updated_at is distinct from (p_expected->>'updated_at')::timestamptz then return jsonb_build_object('ok',false,'reason','conflict'); end if;
      update public.consignment_deals set status=v_to,
        spec=case v_action when 'deposit' then jsonb_set(spec,'{deposit_received_at}',to_jsonb(v_date::text)) when 'complete' then jsonb_set(spec,'{reflection}',p_input->'note') else spec end,
        inspected_at=case when v_action='inspect' then v_date else inspected_at end,
        paid_at=case when v_action='pay' then v_date else paid_at end,
        notes=case when v_action='inspect' then nullif(p_input->>'note','') else notes end
        where id=p_id returning * into v_deal;
      if v_deal.id is null then raise exception 'DEAL_NOT_SAVED'; end if;
    end if;
    v_row:=to_jsonb(v_deal);
  end if;
  return jsonb_build_object('ok',true,'owner',v_uid,'operation',p_operation,'id',p_id,'input',p_input,'row',v_row);
exception when others then
  return jsonb_build_object('ok',false,'reason','save_rejected','code',sqlstate);
end $function$

CREATE OR REPLACE FUNCTION public.trg_block_third_party_open()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'open'
     and (tg_op = 'INSERT' or old.status is distinct from 'open') then
    -- 運営者（app_admins）の自己募集は常に可
    if exists (select 1 from public.app_admins a where a.auth_id = new.farmer_id) then
      return new;
    end if;
    -- 第三者の求人は届出受理フラグが立つまで公開不可
    if not exists (select 1 from public.app_settings
                    where key = 'third_party_publish_allowed' and value = 'true') then
      raise exception '第三者の求人は、特定募集情報等提供事業者の届出が完了するまで公開できません（CLAUDE.md 2026-07-13）';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_notify_job_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_crop text; v_task text; v_status text;
begin
  select crop, task, status into v_crop, v_task, v_status
    from public.jobs where job_number = new.job_number;

  perform public.notify_admins('job_report',
    '求人に通報：#' || new.job_number || '　【' || new.target_field || '】' || new.issue_type);

  begin
    perform public.send_admin_email(
      '[通報] 求人 #' || new.job_number || '　【' || new.target_field || '】' || new.issue_type,
      '求人への通報が届きました。' || E'\n\n' ||
      '■ 求人：#' || new.job_number || '（' || coalesce(v_crop,'') || ' ' || coalesce(v_task,'')
        || '・現在 ' || coalesce(v_status,'?') || '）' || E'\n' ||
      '■ 対象項目：' || new.target_field || E'\n' ||
      '■ 問題の種類：' || new.issue_type || E'\n' ||
      '■ 詳細：' || E'\n' || coalesce(nullif(new.detail,''),'（記載なし）') || E'\n\n' ||
      '確認：https://chitose-bank.com/#/admin/review/' || new.job_number || E'\n' ||
      '（苦情への対応は遅滞なく。対応後は job_reports.status を resolved に）'
    );
  exception when others then null;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.worker_profile_for_farmer(p_worker_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v json; v_priv boolean; v_entitled boolean; v_pending boolean;
begin
  if auth.uid() is null or p_worker_id is null then return null; end if;
  -- 特権＝本人 or 運営（審査中でも見える・全安全列）。農家＝応募を受けた関係のみ・審査中は伏せる
  v_priv := (auth.uid() = p_worker_id) or exists (select 1 from public.app_admins a where a.auth_id = auth.uid());
  v_entitled := v_priv or ( not public.is_account_moderated(p_worker_id)
                            and exists (select 1 from public.applications a
                                         where a.worker_id = p_worker_id and a.farmer_id = auth.uid()) );
  if not v_entitled then return null; end if;
  -- 審査中（未承認の自己紹介がある）は農家に見せない＝本文は返さず under_review のみ（2026-07-19の非表示ゲートを維持）
  if not v_priv then
    select (nullif(btrim(coalesce(pr_pending,'')),'') is not null
            or (pr_qa_pending is not null and jsonb_typeof(pr_qa_pending)='array'
                and jsonb_array_length(pr_qa_pending) > 0))
      into v_pending from public.worker_profiles where auth_id = p_worker_id;
    if coalesce(v_pending,false) then return json_build_object('under_review', true); end if;
  end if;
  select json_build_object(
    'auth_id', wp.auth_id, 'nickname', wp.nickname, 'pr', wp.pr, 'avatar_url', wp.avatar_url,
    'created_at', wp.created_at, 'residence_city', wp.residence_city, 'transport', wp.transport,
    'farm_experience', wp.farm_experience, 'experienced_tasks', wp.experienced_tasks,
    'physical_level', wp.physical_level, 'pr_qa', wp.pr_qa, 'interests', wp.interests,
    'languages', wp.languages, 'self_declared', wp.self_declared, 'experience_entries', wp.experience_entries,
    'work_mood', wp.work_mood, 'learning_pref', wp.learning_pref, 'work_pattern', wp.work_pattern
  ) into v from public.worker_profiles wp where wp.auth_id = p_worker_id;
  return v;  -- pr_pending / pr_qa_pending / pr_hidden_original / pr_revision_targets は含めない
end; $function$

CREATE OR REPLACE FUNCTION public.job_wage_floor_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_floor integer; v_minutes integer; v_break integer; v_actual integer; v_hourly numeric; v_start date; v_end date;
begin
 if new.status not in ('pending','open') then return new; end if;
 if tg_op='UPDATE' and old.status='open' and new.status='open' and (new.prefecture,new.date_start,new.date_end,new.work_time,new.break_time,new.daily_wage,new.hourly_wage) is not distinct from (old.prefecture,old.date_start,old.date_end,old.work_time,old.break_time,old.daily_wage,old.hourly_wage) then return new; end if;
 v_start:=new.date_start; v_end:=coalesce(new.date_end,new.date_start);
 if v_start is null or v_end is null or v_end<v_start then raise exception '最低賃金を判定できません。就業日を確認してください'; end if;
 if coalesce(new.prefecture,'')='' then raise exception '最低賃金を判定できません。勤務地の都道府県を確認してください'; end if;
 -- 就業期間中に施行される最高額。未登録の地域は必ず拒否。
 select max(m.hourly_wage) into v_floor from public.minimum_wages m where m.prefecture=new.prefecture and m.effective_from<=v_end and m.effective_from=(select max(m2.effective_from) from public.minimum_wages m2 where m2.prefecture=m.prefecture and m2.effective_from<=greatest(v_start,m.effective_from));
 if v_floor is null then raise exception '最低賃金情報が確認できません。運営に連絡してください'; end if;
 if coalesce(btrim(new.hourly_wage),'')<>'' then
   if btrim(new.hourly_wage)!~'^[0-9]+$' or btrim(new.hourly_wage)::numeric<v_floor then raise exception '時給が就業期間の最低賃金（%円）を下回るか不正です',v_floor; end if;
 end if;
 if coalesce(btrim(new.daily_wage),'')<>'' then
   if btrim(new.daily_wage)!~'^[0-9]+$' then raise exception '日給は数字で入力してください'; end if;
   v_minutes:=public.job_scheduled_minutes(new.work_time);
   if v_minutes is null then raise exception '勤務時間を確認できません'; end if;
   v_break:=coalesce((regexp_match(coalesce(new.break_time,''),'([0-9]+)'))[1]::integer,0);
   v_actual:=v_minutes-greatest(v_break,case when v_minutes>480 then 60 when v_minutes>360 then 45 else 0 end);
   if v_actual<=0 then raise exception '実働時間を確認できません'; end if;
   v_hourly:=btrim(new.daily_wage)::numeric*60/v_actual;
   if v_hourly<v_floor then raise exception '日給の換算時給が就業期間の最低賃金（%円）を下回っています',v_floor; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.jq_ng_check(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p is null or btrim(p) = '' then return '内容が空です'; end if;
  if char_length(p) > 500 then return '500文字以内でお願いします'; end if;
  if p ~ '0\d{1,4}[-‐−ー\s]?\d{1,4}[-‐−ー\s]?\d{3,4}' then
    return '電話番号は記載できません（連絡はサイト内でお願いします）'; end if;
  if p ~* '[a-z0-9._%+-]+@[a-z0-9.-]+' then
    return 'メールアドレスは記載できません'; end if;
  if p ~* 'https?://|www\.' then return 'URLは記載できません'; end if;
  return null;
end; $function$

CREATE OR REPLACE FUNCTION public.job_meeting_place(p_job_number integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_address text; v_town text; v_city text; v_pref text;
begin
  -- 資格：その求人に approved 以降の応募を持つ働き手、または求人の農家本人
  if not exists (
    select 1 from public.applications a
     where a.job_number = p_job_number
       and (a.worker_id = auth.uid() and a.status in ('approved','meeting','interview','contracted','working','completed'))
  ) and not exists (
    select 1 from public.jobs j
     where j.job_number = p_job_number and j.farmer_id = auth.uid()
  ) then
    return json_build_object('ok', false, 'reason', 'not_entitled');
  end if;

  select prefecture, city, town, address into v_pref, v_city, v_town, v_address
    from public.jobs where job_number = p_job_number;

  return json_build_object('ok', true,
    'full_address', coalesce(v_pref,'') || coalesce(v_city,'') || coalesce(v_town,'') || ' ' || coalesce(v_address,''));
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_session_start()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_recent int;
begin
  if exists (select 1 from public.app_admins a where a.auth_id = new.auth_id) then
    return new;
  end if;
  select count(*) into v_recent from public.page_events
   where auth_id = new.auth_id and id <> new.id
     and ts > now() - interval '30 minutes';
  if v_recent = 0 then
    v_name := public.resolve_actor_name(new.auth_id);
    begin
      perform public.send_admin_email(
        '[操作開始] ' || v_name || ' → ' || new.page_hash,
        v_name || ' がサイトの操作を始めました。' || E'\n' ||
        '最初のページ：' || new.page_hash || E'\n' ||
        '時刻：' || to_char(now() at time zone 'Asia/Tokyo','MM/DD HH24:MI:SS') || E'\n\n' ||
        '（離脱後30分で軌跡の総括が届きます）');
    exception when others then null; end;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.job_time_notice_mail(p_app uuid, p_kind text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job int; v_wt text; v_ref text; v_head text;
  v_subject text; v_body text; v_btn_label text; v_btn_url text; v_sub text := '';
  v_emg text;
begin
  select a.job_number, j.work_time into v_job, v_wt
    from public.applications a join public.jobs j on j.job_number = a.job_number
   where a.id = p_app;
  if v_job is null then return null; end if;

  v_emg  := 'https://chitose-bank.com/#/emergency/' || p_app;
  v_ref  := public.job_ref(v_job, p_role);
  v_head := '■ ' || v_ref || '（' || coalesce(v_wt,'時間未設定') || '）' || E'\n\n';

  if p_kind = 'before_60' and p_role = 'worker' then
    v_subject := '仕事開始まであと1時間です';
    v_body := '本日の仕事開始まであと1時間です。' || E'\n' ||
              '集合場所、持ち物、移動状況をご確認ください。' || E'\n\n' ||
              '遅れそうな場合や、予定どおり向かうことが難しい場合は、早めに農家へご連絡ください。';
    v_btn_label := '緊急連絡をする'; v_btn_url := v_emg;

  elsif p_kind = 'before_60' and p_role = 'farmer' then
    v_subject := '作業開始まであと1時間です';
    v_body := '本日の作業開始まであと1時間です。' || E'\n' ||
              '受け入れ準備、作業内容、集合場所をご確認ください。' || E'\n\n' ||
              '予定の変更や働き手への連絡が必要な場合は、早めにご連絡ください。';
    v_btn_label := '緊急連絡をする'; v_btn_url := v_emg;

  elsif p_kind = 'start' and p_role = 'worker' then
    v_subject := '仕事開始の時間です';
    v_body := '仕事の開始時刻になりました。' || E'\n' ||
              '開始時刻は自動で記録されます。' || E'\n\n' ||
              '作業内容と本日の予定をご確認のうえ、作業を開始してください。';
    v_btn_label := '今日の仕事を見る'; v_btn_url := 'https://chitose-bank.com/#/calendar';
    v_sub := '遅刻・中止などの連絡はこちら';

  elsif p_kind = 'start' and p_role = 'farmer' then
    v_subject := '仕事開始の時間です';
    v_body := '予定の仕事開始時刻になりました。' || E'\n' ||
              '開始の時刻は自動で記録されています。' || E'\n\n' ||
              '働き手が到着し、実際に作業を始めたことをご確認ください。' || E'\n' ||
              '働き手が来ていない場合は、作業のあとの完了の記録で「来なかった」として残せます。';
    v_btn_label := '今日の仕事を見る'; v_btn_url := 'https://chitose-bank.com/#/calendar';
    v_sub := '急ぎの連絡はこちら';

  elsif p_kind = 'end' and p_role = 'worker' then
    v_subject := '本日の作業終了の時間です';
    v_body := '本日の作業終了時刻になりました。' || E'\n\n' ||
              '作業お疲れさまでした。' || E'\n' ||
              '報酬は当日その場で現金でお受け取りください。' || E'\n\n' ||
              '次の作業日は「今日の仕事」からご確認いただけます。';
    v_btn_label := '今日の仕事を見る'; v_btn_url := 'https://chitose-bank.com/#/calendar';
    v_sub := '急ぎの連絡はこちら';

  elsif p_kind = 'end' and p_role = 'farmer' then
    v_subject := '本日の作業終了の時間です';
    v_body := '本日の作業終了時刻になりました。' || E'\n\n' ||
              '報酬は当日その場で現金でお渡しください。' || E'\n\n' ||
              '完了の記録と評価は、全ての日程が終わったあとにお願いします。';
    v_btn_label := '今日の仕事を見る'; v_btn_url := 'https://chitose-bank.com/#/calendar';
    v_sub := '急ぎの連絡はこちら';

  elsif p_kind = 'all_done' and p_role = 'worker' then
    v_subject := '全日程が終了しました｜評価をお願いします';
    v_body := 'この求人の全ての日程が終了しました。' || E'\n\n' ||
              '作業お疲れさまでした。' || E'\n' ||
              '報酬は当日その場で現金でお受け取りください。' || E'\n\n' ||
              '最後に農家への評価をお願いします。';
    v_btn_label := '農家を評価する'; v_btn_url := 'https://chitose-bank.com/#/calendar/todo/w_review';

  elsif p_kind = 'all_done' and p_role = 'farmer' then
    v_subject := '全日程が終了しました｜完了を確認してください';
    v_body := 'この求人の全ての日程が終了しました。' || E'\n\n' ||
              '報酬は当日その場で現金でお渡しください。' || E'\n\n' ||
              '作業完了を記録し、働き手を評価してください。';
    v_btn_label := '完了して評価する'; v_btn_url := 'https://chitose-bank.com/#/calendar/todo/complete';

  else
    return null;
  end if;

  return jsonb_build_object(
    'subject', '[chitose-bank] ' || v_subject,
    'body', v_head || v_body || E'\n\n' || v_btn_label || '：' || E'\n' || v_btn_url ||
            case when v_sub <> '' then E'\n\n' || v_sub || '：' || E'\n' || v_emg else '' end,
    'html',
      '<div style="font-family:sans-serif;max-width:560px;margin:0 auto;">'
      || '<h2 style="font-size:17px;color:#222;">' || public.h(v_subject) || '</h2>'
      || '<p style="font-size:13px;color:#717171;">' || public.h(v_ref)
      || '（' || public.h(coalesce(v_wt,'時間未設定')) || '）</p>'
      || '<p style="font-size:14px;color:#222;line-height:1.9;white-space:pre-wrap;margin:12px 0 20px;">'
      || public.h(v_body) || '</p>'
      || '<a href="' || v_btn_url || '" style="display:inline-block;background:#00A86B;color:#fff;'
      || 'padding:14px 32px;border-radius:10px;text-decoration:none;font-size:14px;font-weight:bold;">'
      || public.h(v_btn_label) || '</a>'
      || case when v_sub <> '' then
           '<p style="font-size:12px;margin:16px 0 0;"><a href="' || v_emg
           || '" style="color:#717171;text-decoration:underline;">' || public.h(v_sub) || '</a></p>'
         else '' end
      || '</div>');
end $function$

CREATE OR REPLACE FUNCTION public.set_job_opened_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'open' and (tg_op = 'INSERT' or old.status is distinct from 'open') then
    new.opened_at := now();
    new.unlisted_at := null;
    new.unlisted_reason := null;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.update_account_holder_self(p_patch jsonb, p_source text DEFAULT 'app'::text)
 RETURNS json
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_allowed text[] := array['full_name','postal_code','address','contact_email',
    'contact_phone','company_name','birth_date'];
  k text; v_n int;
begin
  if auth.uid() is null then return json_build_object('ok',false,'reason','not_authenticated'); end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    return json_build_object('ok',false,'reason','bad_patch');
  end if;
  for k in select jsonb_object_keys(p_patch) loop
    if not (k = any(v_allowed)) then
      return json_build_object('ok',false,'reason','key_not_allowed','key',k);
    end if;
  end loop;
  perform set_config('app.change_source', coalesce(nullif(btrim(p_source),''),'app'), true);
  update public.account_holders set
    full_name     = case when p_patch ? 'full_name'     then p_patch->>'full_name'     else full_name end,
    postal_code   = case when p_patch ? 'postal_code'   then p_patch->>'postal_code'   else postal_code end,
    address       = case when p_patch ? 'address'       then p_patch->>'address'       else address end,
    contact_email = case when p_patch ? 'contact_email' then p_patch->>'contact_email' else contact_email end,
    contact_phone = case when p_patch ? 'contact_phone' then p_patch->>'contact_phone' else contact_phone end,
    company_name  = case when p_patch ? 'company_name'  then p_patch->>'company_name'  else company_name end,
    birth_date    = case when p_patch ? 'birth_date'    then nullif(p_patch->>'birth_date','')::date else birth_date end
  where auth_id = auth.uid();
  get diagnostics v_n = row_count;
  return json_build_object('ok', v_n > 0, 'updated', v_n);
end; $function$

CREATE OR REPLACE FUNCTION public.admin_preview_job_time_notices(p_to uuid, p_app uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_app uuid; v_kind text; v_role text; v_mail jsonb; v_n int := 0;
begin
  if auth.uid() is not null
     and not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_admin');
  end if;

  v_app := p_app;
  if v_app is null then
    select a.id into v_app
      from public.applications a join public.jobs j on j.job_number = a.job_number
     where a.terms_snapshot is not null and j.work_time ~ '^\d{1,2}:\d{2}'
     order by a.created_at desc limit 1;
  end if;
  if v_app is null then return jsonb_build_object('ok', false, 'reason', 'no_sample'); end if;

  foreach v_kind in array array['before_60','before_15','start','end'] loop
    foreach v_role in array array['worker','farmer'] loop
      v_mail := public.job_time_notice_mail(v_app, v_kind, v_role);
      if v_mail is not null then
        perform public.send_user_email(p_to, v_mail->>'subject',
          '※これは確認用の送信です（実際の予定ではありません）。' || E'\n' ||
          '※宛先の別：' || case when v_role='worker' then '働き手に届く文面' else '農家に届く文面' end || E'\n' ||
          '――――――――――' || E'\n\n' || (v_mail->>'body'),
          '<p style="font-family:sans-serif;font-size:12px;color:#B0B0B0;max-width:560px;margin:0 auto 12px;">'
          || '※これは確認用の送信です（実際の予定ではありません）／'
          || case when v_role='worker' then '働き手に届く文面' else '農家に届く文面' end || '</p>'
          || (v_mail->>'html'));
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  return jsonb_build_object('ok', true, 'sent', v_n, 'application_id', v_app);
end $function$

CREATE OR REPLACE FUNCTION public.cancel_application(p_application_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_worker uuid; v_farmer uuid; v_status text; v_job int; v_name text;
  v_wref text; v_jst text; v_wtext text; v_whtml text;
begin
  select worker_id, farmer_id, status, job_number into v_worker, v_farmer, v_status, v_job
    from public.applications where id = p_application_id;
  if v_worker is null then return json_build_object('ok', false, 'reason','not_found'); end if;
  if v_worker <> auth.uid() then return json_build_object('ok', false, 'reason','not_yours'); end if;
  if v_status = 'canceled' then return json_build_object('ok', true, 'already', true); end if;
  if v_status <> 'applied' then
    return json_build_object('ok', false, 'reason','already_decided', 'status', v_status);
  end if;
  -- 物理deleteでなく論理削除（2026-08-16）：messages（履歴）を消さずに取り消しを記録する。
  -- 再応募は部分unique index（status<>'canceled'）のおかげで新しい applied 行として通る。
  update public.applications set status = 'canceled', canceled_at = now()
   where id = p_application_id;
  begin
    insert into public.messages (application_id, sender_id, body)
    values (p_application_id, v_worker, '応募を取り消しました。');
  exception when others then null; end;
  v_name := public.resolve_actor_name(v_worker);
  insert into public.notifications (farmer_id, type, message)
  values (v_farmer, 'application_cancelled',
          '応募が取り消されました：求人 #' || v_job || '　' || v_name || 'さん');
  begin
    perform public.send_user_email(v_farmer,
