CREATE OR REPLACE FUNCTION private.can_read_listing_photo(p_bucket text, p_name text, p_owner text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_url text;
begin
  if v_uid is null or p_bucket not in ('job-photos','consignment-photos') then return false; end if;
  if exists (select 1 from public.app_admins a where a.auth_id = v_uid) then return true; end if;
  if p_owner = v_uid::text then return true; end if;
  if exists (select 1 from private.listing_photo_legacy_access l
    where l.bucket_id=p_bucket and l.object_name=p_name and l.farmer_id=v_uid) then return true; end if;

  -- Consignment records are administrator-only today. Do not invent a public
  -- photo permission for those otherwise private records.
  if p_bucket <> 'job-photos' then return false; end if;
  -- Non-owners may download an entitled photo, never enumerate or sign it.
  if not storage.allow_any_operation(array['object.get_authenticated','object.get_authenticated_info']) then return false; end if;
  v_url := 'https://aegwepgtmwcnwzybpgsh.supabase.co/storage/v1/object/public/' || p_bucket || '/' || p_name;
  return exists (
    select 1 from public.jobs j
    where j.status in ('open','closed')
      and (p_owner = j.farmer_id::text or exists (
        select 1 from private.listing_photo_legacy_access l
        where l.bucket_id=p_bucket and l.object_name=p_name and l.farmer_id=j.farmer_id))
      and exists (select 1 from private.listing_photo_urls(j.photos,j.danger_places,j.danger_tasks) u(url) where u.url=v_url)
      and (
        (j.unlisted_reason is null and not public.is_account_moderated(j.farmer_id)
          and (j.status='open' or (j.headcount > 0 and
            (select count(*) from public.applications a where a.job_number=j.job_number
              and a.terms_confirmed_worker_at is not null and a.terms_confirmed_farmer_at is not null) >= j.headcount)))
        or exists (select 1 from public.applications a where a.job_number=j.job_number and a.worker_id=v_uid
          and a.status in ('applied','approved','meeting','interview','contracted','working','completed'))
      )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_instant_approve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_instant boolean; v_want boolean;
begin
  if new.status <> 'applied' then return new; end if;
  select instant_approve_repeat into v_instant from public.jobs where job_number = new.job_number;
  if not coalesce(v_instant, false) then return new; end if;
  select exists (
    select 1 from public.repeat_roster rr
     where rr.farmer_id = new.farmer_id and rr.worker_id = new.worker_id
  ) into v_want;
  if not v_want then return new; end if;

  update public.applications set status = 'approved', decided_at = now() where id = new.id;

  insert into public.notifications (farmer_id, type, message) values
    (new.worker_id, 'application_approved',
     '🌟即決で承認されました：求人 #' || new.job_number || '　（承認は採用ではありません。打ち合わせのあとに決まります）'),
    (new.farmer_id, 'application_approved',
     '🌟リピート即決：以前「また呼びたい」と評価した方の応募を自動承認しました（求人 #' || new.job_number || '・採用の決定はチャットで）');
  begin
    perform public.send_user_email(new.worker_id,
      '[chitose-bank] 🌟即決で承認されました：求人 #' || new.job_number,
      '■ ' || public.job_ref(new.job_number,'worker') || E'\n\n' ||
      '応募が、即決で承認されました。' || E'\n' ||
      'この求人者から以前「また呼びたい」の評価を受けているため、選考なしで承認されています。' || E'\n' ||
      '（承認は採用ではありません。採用は打ち合わせ・面接のあとに決まります）' || E'\n\n' ||
      'チャットで日程を確認しましょう：https://chitose-bank.com/#/chats' ||
      public.job_link(new.job_number));
    perform public.send_user_email(new.farmer_id,
      '[chitose-bank] 🌟リピート即決のお知らせ：求人 #' || new.job_number,
      '■ ' || public.job_ref(new.job_number,'farmer') || E'\n\n' ||
      'あなたが以前「また呼びたい」と評価した方から応募があり、' || E'\n' ||
      '求人の設定に基づいて自動承認しました。' || E'\n' ||
      '（承認は採用ではありません。チャットで打ち合わせのうえ「採用する」で決定してください）' || E'\n\n' ||
      '応募者の確認：https://chitose-bank.com/#/profile/employer/applicants' ||
      public.job_link(new.job_number));
  exception when others then null; end;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.set_application_followup(p_application_id uuid, p_kind text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid; v_farmer uuid; v_status text;
  v_held timestamptz; v_handled timestamptz;
begin
  v_caller := auth.uid();
  if v_caller is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  if p_kind not in ('hold','handled','clear') then
    return json_build_object('ok', false, 'reason', 'bad_kind');
  end if;

  select farmer_id, status into v_farmer, v_status
    from public.applications where id = p_application_id;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_farmer <> v_caller then return json_build_object('ok', false, 'reason', 'not_your_application'); end if;
  if v_status <> 'applied' then
    return json_build_object('ok', false, 'reason', 'already_decided', 'status', v_status);
  end if;

  update public.applications
     set held_at    = case p_kind when 'hold'    then now() when 'clear' then null else held_at    end,
         handled_at = case p_kind when 'handled' then now() when 'clear' then null else handled_at end
   where id = p_application_id
  returning held_at, handled_at into v_held, v_handled;

  return json_build_object('ok', true, 'held_at', v_held, 'handled_at', v_handled);
end $function$

