CREATE OR REPLACE FUNCTION public.trg_notify_job_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dates text;
  v_holidays int;
  v_place text;
  v_overtime text;
  v_lines text;
begin
  if new.status <> 'open' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.status,'') = 'open' then return new; end if;
  insert into public.notifications (farmer_id, type, message)
  values (new.farmer_id, 'job_published', 'あなたの求人 #' || new.job_number || ' が公開されました');
  begin
    v_dates := coalesce(new.date_start::text, '未設定');
    if new.date_end is not null and new.date_end <> new.date_start then
      v_dates := new.date_start::text || ' 〜 ' || new.date_end::text;
    end if;
    v_holidays := case when jsonb_typeof(new.holidays) = 'array' then jsonb_array_length(new.holidays) else 0 end;
    if v_holidays > 0 then v_dates := v_dates || '（休日' || v_holidays || '日）'; end if;
    v_place := coalesce(new.prefecture,'') || coalesce(new.city,'') || coalesce(new.town,'');
    v_overtime := case when new.overtime_policy = 'あり'
      then 'あり' || case when coalesce(btrim(new.overtime_detail),'') <> '' then '（' || btrim(new.overtime_detail) || '）' else '' end
      else coalesce(nullif(btrim(new.overtime_policy),''), '未設定') end;
    v_lines :=
      '・作物・作業：' || trim(coalesce(new.crop,'') || ' ' || coalesce(new.task,'')) || E'\n' ||
      '・場所：' || coalesce(nullif(v_place,''), '未設定') || E'\n' ||
      '・作業日程：' || v_dates || E'\n' ||
      '・勤務時間：' || coalesce(nullif(btrim(new.work_time),''), '未設定') ||
        case when coalesce(btrim(new.break_time),'') <> '' then '（休憩 ' || btrim(new.break_time) || '）' else '' end || E'\n' ||
      '・日給：' || case when coalesce(btrim(new.daily_wage),'') <> '' then btrim(new.daily_wage) || '円' else '未設定' end || E'\n' ||
      '・募集人数：' || coalesce(new.headcount::text, '未設定') || '名' || E'\n' ||
      '・時間外労働：' || v_overtime || E'\n' ||
      '・掲載時刻：' || to_char(now() at time zone 'Asia/Tokyo', 'YYYY年FMMM月FMDD日 HH24:MI') || '（日本時間）';
    perform public.send_user_email(new.farmer_id,
      '[chitose-bank] 掲載完了：求人 #' || new.job_number || '「' || trim(coalesce(new.crop,'') || ' ' || coalesce(new.task,'')) || '」',
      '掲載が完了しました！働き手に公開されています。' || E'\n\n' ||
      '■ ' || public.job_ref(new.job_number,'farmer') || E'\n' ||
      v_lines || E'\n' ||
      public.job_link(new.job_number) || E'\n\n' ||
      '応募が入ると、メールとアプリのお知らせでお伝えします。' || E'\n' ||
      '内容の修正・一時非公開は、お仕事タブの「公開中」からいつでもできます。' || E'\n' ||
      '最終作業日が過ぎると、掲載は自動で終了します。' || E'\n\n' ||
      '困ったときは：' || E'\n' ||
      '・ヘルプ：https://chitose-bank.com/#/help' || E'\n' ||
      '・お問い合わせ：t5fki6643qty@gmail.com');
  exception when others then null; end;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.send_application_followups()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; v_hours numeric; v_stage int; v_due int; v_mail jsonb; v_ins int;
begin
  for r in
    select a.id as app_id, a.farmer_id, a.job_number, a.created_at
      from public.applications a
      join public.jobs j on j.job_number = a.job_number
     where a.status = 'applied'
       and a.held_at is null and a.handled_at is null
       and a.created_at <= now() - interval '12 hours'
  loop
    v_hours := extract(epoch from (now() - r.created_at)) / 3600.0;

    v_due := null;
    foreach v_stage in array array[12,24,36,48,60,72] loop
      if v_hours >= v_stage then v_due := v_stage; end if;
    end loop;
    if v_due is null then continue; end if;

    foreach v_stage in array array[12,24,36,48,60,72] loop
      exit when v_stage >= v_due;
      insert into public.application_followup_notices (application_id, stage_hours, sent)
      values (r.app_id, v_stage, false) on conflict do nothing;
    end loop;

    insert into public.application_followup_notices (application_id, stage_hours, sent)
    values (r.app_id, v_due, true) on conflict do nothing;
    get diagnostics v_ins = row_count;
    if v_ins = 0 then continue; end if;

    v_mail := public.application_followup_mail(r.app_id, v_due);
    if v_mail is not null then
      begin
        perform public.send_user_email(r.farmer_id, v_mail->>'subject', v_mail->>'body');
      exception when others then null; end;
    end if;

    if v_due = 72 then
      begin
        perform public.notify_admins('application_no_reply_72h',
          '72時間未回答：求人 #' || r.job_number);
        perform public.send_admin_email(
          '[chitose-bank][運営] 72時間未回答の応募：求人 #' || r.job_number,
          '求人 #' || r.job_number || ' の応募が72時間未回答です。' || E'\n' ||
          '応募の受付：' || to_char(r.created_at at time zone 'Asia/Tokyo','YYYY/MM/DD HH24:MI') || E'\n\n' ||
          '仕事中ページ：https://chitose-bank.com/#/admin/working' || E'\n' ||
          '求人ページ：https://chitose-bank.com/#/work/job/' || r.job_number);
      exception when others then null; end;
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.admin_preview_application_followups(p_to uuid, p_app uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_app uuid; v_stage int; v_mail jsonb; v_n int := 0;
begin
  if auth.uid() is not null
     and not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_admin');
  end if;

  v_app := p_app;
  if v_app is null then
    select id into v_app from public.applications order by created_at desc limit 1;
  end if;
  if v_app is null then return jsonb_build_object('ok', false, 'reason', 'no_sample'); end if;

  foreach v_stage in array array[12,24,36,48,60,72] loop
    v_mail := public.application_followup_mail(v_app, v_stage);
    if v_mail is not null then
      perform public.send_user_email(p_to, v_mail->>'subject',
        '※これは確認用の送信です（実際の督促ではありません）。' || E'\n' ||
        '※経過：' || v_stage || '時間' || E'\n' ||
        '――――――――――' || E'\n\n' || (v_mail->>'body'));
      v_n := v_n + 1;
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'sent', v_n, 'application_id', v_app);
end $function$

CREATE OR REPLACE FUNCTION public.jp_val(p jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v text;
begin
  if p is null or p = 'null'::jsonb then return '（未設定）'; end if;
  if p = 'true'::jsonb then return 'はい'; end if;
  if p = 'false'::jsonb then return 'いいえ'; end if;
  v := p #>> '{}';
  if v = '' then return '（空欄）'; end if;
  v := case v
    when 'open' then '公開中' when 'draft' then '作成中' when 'pending' then '審査待ち'
    when 'applied' then '応募中' when 'approved' then '承認済み' when 'completed' then '完了'
    when 'rejected' then '見送り' when 'expired' then '失効'
    when 'farmer_to_worker' then '農家→働き手' when 'worker_to_farmer' then '働き手→農家'
    when 'late' then '遅れる連絡' when 'absent_notice' then '欠勤の連絡'
    when 'cancel' then '中止の連絡' when 'postpone' then '延期の連絡'
    when 'dispute_no_show' then '欠勤記録への異議'
    when 'together' then '一緒に作業する' when 'explain_then_leave' then '最初に説明して任せる'
    when 'on_call' then '必要な時だけ声かけ'
    else v end;
  if length(v) > 80 then v := left(v, 80) || '…'; end if;
  return v;
end; $function$

CREATE OR REPLACE FUNCTION public.sync_my_open_job(p_owner uuid, p_id uuid, p_expected jsonb, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_job public.jobs%rowtype;
  v_allowed text[] := array['crop','task','zip','prefecture','city','town','address','date_label','date_start','date_end','holidays','headcount','pay_type','hourly_wage','daily_wage','work_time','break_time','nearest_station','commute_time','job_exp','beginner_ok','instant_approve_repeat','perks','experienced_preferred','notes','belongings','cautions','overtime_policy','overtime_detail','place_change_scope','task_change_scope','danger_places','danger_tasks','photos','work_video_url','work_video_job_consent','work_video_related_consent','work_video_consent_at','work_video_consent_version','draft_step','draft_step_id','lat','lng','geo_radius_m','geocoded_from'];
  v_current jsonb;
  v_result jsonb;
begin
  if v_uid is null or v_uid is distinct from p_owner then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    return jsonb_build_object('ok',false,'reason','bad_patch');
  end if;
  if exists (select 1 from jsonb_object_keys(p_patch) k where k <> all(v_allowed)) then
    return jsonb_build_object('ok',false,'reason','bad_field');
  end if;
  if not exists (select 1 from public.account_holders a
                 where a.auth_id=v_uid and a.agreed_privacy_version=public.current_privacy_version()) then
    return jsonb_build_object('ok',false,'reason','consent_required');
  end if;
  select * into v_job from public.jobs where id=p_id and farmer_id=v_uid for update;
  if not found then return jsonb_build_object('ok',false,'reason','conflict','row',null); end if;
  if v_job.status <> 'open' then return jsonb_build_object('ok',false,'reason','conflict','row',to_jsonb(v_job)); end if;

    -- job_sync_value_equality_v1: 比較前に同意時刻だけをDB型へ揃える。
    -- 本人・同意・許可列・行ロック・状態検査を通過した行にのみ適用する。
    if p_patch ? 'work_video_consent_at' then
      p_patch := p_patch || jsonb_build_object('work_video_consent_at',
        (p_patch->>'work_video_consent_at')::timestamptz);
    end if;
    if jsonb_typeof(p_expected) = 'object' and p_expected ? 'work_video_consent_at' then
      p_expected := p_expected || jsonb_build_object('work_video_consent_at',
        (p_expected->>'work_video_consent_at')::timestamptz);
    end if;
if not exists (
    select 1 from jsonb_each(p_patch - 'draft_step') p
    where (to_jsonb(v_job)->p.key) is distinct from p.value
  ) then
    return jsonb_build_object('ok',true,'row',to_jsonb(v_job));
  end if;
  select jsonb_object_agg(key,value) into v_current from jsonb_each(to_jsonb(v_job))
    where key = any(v_allowed || array['status']);
  if p_expected is null or v_current is distinct from p_expected then
    return jsonb_build_object('ok',false,'reason','conflict','row',to_jsonb(v_job));
  end if;
  v_result := public.update_my_open_job(v_job.job_number, p_patch - 'draft_step')::jsonb;
  if not coalesce((v_result->>'ok')::boolean,false) then return v_result; end if;
  select * into v_job from public.jobs where id=p_id and farmer_id=v_uid;
  return jsonb_build_object('ok',true,'row',to_jsonb(v_job));
end $function$

CREATE OR REPLACE FUNCTION public.save_my_privacy_consent(p_auth_id uuid, p_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_version text;
begin
  if auth.uid() is null or auth.uid() is distinct from p_auth_id then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_version is null or p_version is distinct from public.current_privacy_version() then
    raise exception 'POLICY_CHANGED' using errcode='22023';
  end if;
  update public.account_holders set agreed_privacy_version=p_version
    where auth_id=auth.uid() and agreed_privacy_version is distinct from p_version;
  select agreed_privacy_version into v_version from public.account_holders where auth_id=auth.uid();
  return jsonb_build_object('agreed_privacy_version',v_version);
end $function$

CREATE OR REPLACE FUNCTION public.messages_history_lock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'messages are immutable history: delete is not allowed（チャット履歴は削除できません・2026-07-19恒久ルール）';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.application_id IS DISTINCT FROM OLD.application_id
     OR NEW.sender_id IS DISTINCT FROM OLD.sender_id
     OR NEW.body IS DISTINCT FROM OLD.body
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'messages are immutable history: only read_at may change（本文・送信者・時刻は変更できません）';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.job_ref(p_job integer, p_viewer text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_crop text; v_task text; v_farmer uuid; v_farm text; v_title text;
begin
  select crop, task, farmer_id into v_crop, v_task, v_farmer
    from public.jobs where job_number = p_job;
  if v_farmer is null then return '求人 #' || p_job; end if;
  v_title := trim(coalesce(v_crop,'') || ' ' || coalesce(v_task,''));
  if v_title = '' then v_title := '内容未設定'; end if;
  if p_viewer = 'farmer' then
    return 'あなたの求人 #' || p_job || '「' || v_title || '」';
  else
    select nullif(nickname,'') into v_farm from public.employer_profiles where auth_id = v_farmer;
    v_farm := coalesce(v_farm, public.resolve_actor_name(v_farmer), '農家');
    return v_farm || 'さんの求人 #' || p_job || '「' || v_title || '」';
  end if;
end; $function$

CREATE OR REPLACE FUNCTION public.trg_consign_freeze_spec()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'agreed' and (tg_op = 'UPDATE' and old.status is distinct from 'agreed') then
    if new.spec_snapshot is null then
      new.spec_snapshot := new.spec;
      new.snapshot_at := now();
    end if;
    if new.agreed_at is null then new.agreed_at := (now() at time zone 'Asia/Tokyo')::date; end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.report_chat_message(p_message_id uuid, p_reason text, p_detail text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_app uuid; v_body text; v_sender uuid;
begin
  if auth.uid() is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  select m.application_id, m.body, m.sender_id into v_app, v_body, v_sender
    from public.messages m
    join public.applications a on a.id = m.application_id
   where m.id = p_message_id
     and (a.worker_id = auth.uid() or a.farmer_id = auth.uid());
  if v_app is null then return json_build_object('ok', false, 'reason', 'not_party'); end if;
  if coalesce(trim(p_reason), '') = '' then return json_build_object('ok', false, 'reason', 'no_reason'); end if;

  insert into public.message_reports (message_id, application_id, reporter_id, body_snapshot, sender_id_snapshot, reason, detail)
  values (p_message_id, v_app, auth.uid(), v_body, v_sender, trim(p_reason), nullif(trim(coalesce(p_detail,'')), ''));

  begin
    perform public.notify_admins('message_reported', 'チャットのコメント報告：' || trim(p_reason) || '「' || left(v_body, 40) || '」');
  exception when others then null; end;
  return json_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_pending_application(p_job integer, p_available_dates jsonb DEFAULT NULL::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_farmer uuid; v_ds date; v_de date; v_is_period boolean;
begin
  if auth.uid() is null then return json_build_object('ok',false,'reason','not_logged_in'); end if;
  -- 停止・追放中の働き手は仮応募も預からない（絶対に通さない・2026-08-17）
  if public.is_account_moderated(auth.uid()) then
    return json_build_object('ok',false,'reason','account_suspended');
  end if;
  select farmer_id, date_start, date_end into v_farmer, v_ds, v_de
    from public.jobs where job_number = p_job and status='open';
  if v_farmer is null then return json_build_object('ok',false,'reason','not_open'); end if;
  -- 求人者が停止・追放中なら募集終了として扱う（apply_to_job と同じ判定・2026-08-16）
  if public.is_account_moderated(v_farmer) then return json_build_object('ok',false,'reason','not_open'); end if;
  -- 自分の求人には応募できない（絶対に通さない・2026-08-17）
  if v_farmer = auth.uid() then return json_build_object('ok',false,'reason','own_job'); end if;
  if exists (select 1 from public.applications
              where job_number = p_job and worker_id = auth.uid()
                and status not in ('rejected','expired')) then
    return json_build_object('ok',false,'reason','already_applied');
  end if;

  -- 期間求人は来られる日が必須（apply_to_job と同一の式・同一の不変条件）
  v_is_period := v_de is not null and v_de <> v_ds;
  if v_is_period then
    if p_available_dates is null
       or not (p_available_dates = '"any"'::jsonb
               or (jsonb_typeof(p_available_dates) = 'array' and jsonb_array_length(p_available_dates) > 0)) then
      return json_build_object('ok', false, 'reason', 'dates_required');
    end if;
  end if;

  insert into public.pending_applications (job_number, worker_id, available_dates)
  values (p_job, auth.uid(), case when v_is_period then p_available_dates else null end)
  on conflict do nothing;
  return json_build_object('ok', true,
    'ready', public.is_worker_profile_ready(auth.uid()));
end; $function$

CREATE OR REPLACE FUNCTION public.notify_push_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
