CREATE OR REPLACE FUNCTION public.trg_protect_terms_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.terms_snapshot is not null then
      raise exception '契約記録（凍結済みスナップショット）のある応募は削除できません';
    end if;
    return old;
  end if;
  if old.terms_snapshot is not null then
    if new.terms_snapshot is distinct from old.terms_snapshot
       or new.terms_confirmed_worker_at is distinct from old.terms_confirmed_worker_at
       or new.terms_confirmed_farmer_at is distinct from old.terms_confirmed_farmer_at then
      raise exception '凍結済みの契約記録は変更できません（全経路で不変）';
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.promote_my_pending_applications()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_n int := 0;
begin
  if auth.uid() is null then return json_build_object('ok',false,'reason','not_logged_in'); end if;
  -- 停止・追放中の働き手は昇格させない（絶対に通さない・2026-08-17 段A）
  if public.is_account_moderated(auth.uid()) then
    return json_build_object('ok', false, 'reason','account_suspended',
      'message','アカウントは停止中のため、応募を届けられません');
  end if;
  -- 本人情報の登録（18歳確認・規約同意の記録）が無いまま農家に応募を届けない（段B・たきと裁定①）
  if not exists (select 1 from public.account_holders h where h.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason','not_registered',
      'message','ご本人の情報の登録がまだ済んでいません');
  end if;
  if not public.is_worker_profile_ready(auth.uid()) then
    return json_build_object('ok', false, 'reason','not_ready',
      'message','プロフィールの必須項目がまだ残っています');
  end if;
  for r in
    select p.id, p.job_number, p.available_dates, j.farmer_id,
           (j.date_end is not null and j.date_end <> j.date_start) as is_period
      from public.pending_applications p
      join public.jobs j on j.job_number = p.job_number
     where p.worker_id = auth.uid() and j.status = 'open'
       and coalesce(j.date_end, j.date_start) >= (now() at time zone 'Asia/Tokyo')::date
  loop
    -- 期間求人で来られる日を持たない仮応募は昇格させない（不変条件を破る応募を作らない）。
    -- 削除もしない＝働き手がもう一度日付を選んで応募し直せる状態を残す。
    if r.is_period and r.available_dates is null then
      continue;
    end if;
    -- 自分の求人／求人者が停止・追放中：昇格させない（入口でも塞いでいるが、預けてから
    -- 求人者の状態は変わりうるので出口でも確認する。ここも削除はしない）
    if r.farmer_id = auth.uid() or public.is_account_moderated(r.farmer_id) then
      continue;
    end if;
    if not exists (select 1 from public.applications
                    where job_number = r.job_number and worker_id = auth.uid()
                      and status not in ('rejected','expired')) then
      insert into public.applications (job_number, worker_id, farmer_id, status, available_dates)
      select r.job_number, auth.uid(), j.farmer_id, 'applied',
             case when r.is_period then r.available_dates else null end
        from public.jobs j where j.job_number = r.job_number;
      v_n := v_n + 1;
    end if;
    delete from public.pending_applications where id = r.id;
  end loop;
  return json_build_object('ok', true, 'promoted', v_n);
end; $function$

CREATE OR REPLACE FUNCTION public.trg_notify_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_w uuid; v_f uuid; v_job int; v_to uuid; v_label text; v_viewer text; v_extra text := '';
        v_by_farmer boolean; v_day text := ''; v_detail text := ''; v_situation text;
begin
  select worker_id, farmer_id, job_number into v_w, v_f, v_job
    from public.applications where id = new.application_id;
  v_to := case when new.actor_id = v_w then v_f else v_w end;
  v_viewer := case when v_to = v_f then 'farmer' else 'worker' end;
  v_by_farmer := (new.actor_id = v_f);
  if new.work_date is not null then
    v_day := to_char(new.work_date, 'MM/DD') || 'の';
  end if;

  v_label := case new.kind
    when 'late' then case when v_by_farmer then '遅刻の記録' else '遅れる連絡' end
    when 'absent_notice' then case when v_by_farmer then '欠勤の記録' else '欠勤の連絡' end
    when 'cancel' then '中止の連絡'
    when 'postpone' then '延期の連絡'
    when 'dispute_no_show' then '欠勤記録への異議'
    when 'no_show_report' then '現地で会えない連絡'
    when 'plan_mismatch' then '「予定と違う」の記録'
    when 'work_incomplete' then case when v_by_farmer then '作業中断の記録' else '作業中断の連絡' end
    else '連絡' end;

  v_detail := case new.detail
    when 'content' then '【作業内容が違った】'
    when 'time' then '【時間が違った】'
    when 'place' then '【場所が違った】'
    when 'pay' then '【報酬・条件が違った】'
    when 'other' then '【その他の食い違い】'
    when 'stopped_early' then '【途中で終了した】'
    when 'could_not_work' then '【作業できなかった】'
    else '' end;
  v_situation := trim(both ' ' from v_detail || ' ' || coalesce(new.reason, ''));

  if new.kind = 'no_show_report' then
    v_extra := E'\n\n至急、チャットまたは電話で相手に連絡してください。' || E'\n' ||
               'この記録は日時とともに保存され、当事者間の話し合いの資料になります。';
  elsif v_by_farmer and new.kind in ('late','absent_notice') then
    -- その日の記録であって、作業全体の出欠ではないことを明示する（最終日の評価で決まる）
    v_extra := E'\n\nこれはその日の記録です。作業全体の完了と出欠は、最終作業日の評価で決まります。' || E'\n' ||
               '心当たりがない場合は、チャットで相手にご確認ください。';
  end if;

  insert into public.notifications (farmer_id, type, message)
  values (v_to, 'attendance_' || new.kind,
          v_day || v_label || '：求人 #' || v_job || '　' || left(v_situation, 40));
  begin
    perform public.send_user_email(v_to,
      '[chitose-bank] ' || v_day || v_label || '：求人 #' || v_job,
      '■ ' || public.job_ref(v_job, v_viewer) || E'\n\n' ||
      '相手方から' || v_day || v_label || 'がありました。' || E'\n' ||
      '状況：' || coalesce(nullif(v_situation, ''), '（記載なし）') || v_extra || E'\n\n' ||
      'チャット：https://chitose-bank.com/#/chats');
  exception when others then null; end;

  -- 運営を呼ぶのは重大イベントだけ（2026-08-21たきと裁定・全件通知は火災報知器になる）：
  -- ①現地で会えない ②欠勤記録への異議（規約第7条3＝運営が双方から事情を確認する義務）
  -- ③「予定と違う」のうち報酬・条件の相違。それ以外はDB保存＋相手方への通知のみ。
  -- 未払いの申告は reviews 側の trg_pay_incident_on_unpaid が別途起票・通知する。
  if new.kind = 'no_show_report' then
    perform public.notify_admins('attendance_no_show_report',
      '🚨現地で会えない連絡：求人 #' || v_job || '（要フォロー：双方に電話）');
  elsif new.kind = 'dispute_no_show' then
    perform public.notify_admins('attendance_dispute_no_show',
      v_day || '欠勤記録への異議：求人 #' || v_job || '（双方から事情の確認を）');
  elsif new.kind = 'plan_mismatch' and new.detail = 'pay' then
    perform public.notify_admins('attendance_plan_mismatch',
      '💰' || v_day || '報酬・条件の相違の記録：求人 #' || v_job || '（要確認）');
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_send_policy_update(p_doc text, p_version text, p_target uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_mail jsonb; v_req bigint; v_n int := 0;
begin
  if auth.uid() is not null
     and not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_admin');
  end if;

  v_mail := public.policy_update_mail(p_doc, p_version);
  if v_mail is null then return jsonb_build_object('ok', false, 'reason', 'bad_doc'); end if;

  for r in
    with all_users as (
      select auth_id from public.account_holders
      union select auth_id from public.worker_profiles
      union select auth_id from public.employer_profiles
    )
    select a.auth_id from all_users a
     where
       (p_target is not null and a.auth_id = p_target)
       or (
         p_target is null
         and not exists (select 1 from auth.users u
                          where u.id = a.auth_id and u.email like 'withdrawn+%')
         and not public.is_account_moderated(a.auth_id)
         and not exists (select 1 from public.policy_update_notices n
                          where n.auth_id = a.auth_id and n.doc = p_doc and n.version = p_version)
       )
  loop
    begin
      v_req := public.send_user_email(r.auth_id, v_mail->>'subject', v_mail->>'body', v_mail->>'html');
    exception when others then v_req := null; end;

    insert into public.policy_update_notices (auth_id, doc, version, request_id)
    values (r.auth_id, p_doc, p_version, v_req)
    on conflict (auth_id, doc, version) do update set sent_at = now(), request_id = excluded.request_id;
    v_n := v_n + 1;
  end loop;

  return jsonb_build_object('ok', true, 'sent', v_n, 'doc', p_doc, 'version', p_version);
end $function$

CREATE OR REPLACE FUNCTION public.contract_emergency_contact(p_application_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_w uuid; v_f uuid; v_snap jsonb; v_other uuid;
  v_started timestamptz; v_completed timestamptz;
  v_ec public.emergency_contacts%rowtype;
  v_cur text; v_agreed text; v_name text; v_phone text;
begin
  select worker_id, farmer_id, terms_snapshot, started_at, work_completed_at
    into v_w, v_f, v_snap, v_started, v_completed
    from public.applications where id = p_application_id;
  if v_w is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if auth.uid() is null then return json_build_object('ok', false, 'reason', 'not_party'); end if;
  if auth.uid() not in (v_w, v_f) then return json_build_object('ok', false, 'reason', 'not_party'); end if;
  if v_snap is null then
    return json_build_object('ok', false, 'reason', 'not_contracted',
      'message', '採用が決まると、お互いの緊急連絡先が表示されます');
  end if;

  -- 仕事の開始から終了までの間だけ表示する（2026-08-25たきと指示「緊急連絡先ボタンは仕事の
  -- 開始から終了まで。それ以外はいかなる理由でも見せない」）。開始＝started_at（自動開始）、
  -- 終了＝work_completed_at（完了の記録）。どちらかが分からない時は見せない側に倒す。
  if v_started is null or v_completed is not null then
    return json_build_object('ok', false, 'reason', 'not_working',
      'message', '緊急連絡先は、仕事の開始から終了までの間だけ表示されます');
  end if;

  v_other := case when auth.uid() = v_f then v_w else v_f end;

  select value into v_cur from public.app_settings where key = 'privacy_version';
  select agreed_privacy_version into v_agreed
    from public.account_holders where auth_id = v_other;
  if v_cur is null or v_agreed is null or v_agreed <> v_cur then
    return json_build_object('ok', false, 'reason', 'not_consented',
      'message', '相手の方がプライバシーポリシーの改訂に同意すると表示されます');
  end if;

  select * into v_ec from public.emergency_contacts where auth_id = v_other;
  -- 「本人」を含め、内容を確認して保存した行だけを開示する。
  -- 自動初期登録・未登録の連絡先は、登録情報で補わない。
  if v_ec.confirmed_at is null then
    return json_build_object('ok', true, 'empty', true, 'reason', 'not_confirmed',
      'message', '相手の緊急連絡先は、ご本人の確認が済んでいないため表示できません');
  end if;
  v_name := nullif(btrim(v_ec.name), '');
  v_phone := nullif(btrim(v_ec.phone), '');
  if v_name is null and v_phone is null then
    return json_build_object('ok', true, 'empty', true,
      'message', '相手の緊急連絡先は登録されていません');
  end if;
  return json_build_object('ok', true, 'empty', false,
    'name', v_name,
    'relation', nullif(btrim(v_ec.relation), ''),
    'phone', v_phone);
end; $function$

CREATE OR REPLACE FUNCTION public.sync_my_job_draft(p_owner uuid, p_id uuid, p_expected jsonb, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_job public.jobs%rowtype;
  v_allowed text[] := array['crop','task','zip','prefecture','city','town','address','date_label','date_start','date_end','holidays','headcount','pay_type','hourly_wage','daily_wage','work_time','break_time','nearest_station','commute_time','job_exp','beginner_ok','instant_approve_repeat','perks','experienced_preferred','notes','belongings','cautions','overtime_policy','overtime_detail','place_change_scope','task_change_scope','danger_places','danger_tasks','photos','work_video_url','work_video_job_consent','work_video_related_consent','work_video_consent_at','work_video_consent_version','draft_step','draft_step_id','lat','lng','geo_radius_m','geocoded_from'];
  v_current jsonb;
  v_columns text;
  v_values text;
begin
  if v_uid is null or v_uid is distinct from p_owner then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_id is null or p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    return jsonb_build_object('ok',false,'reason','bad_patch');
  end if;
  if exists (select 1 from jsonb_object_keys(p_patch) k where k <> all(v_allowed)) then
    return jsonb_build_object('ok',false,'reason','bad_field');
  end if;
  if not exists (select 1 from public.account_holders a
                 where a.auth_id=v_uid and a.agreed_privacy_version=public.current_privacy_version()) then
    return jsonb_build_object('ok',false,'reason','consent_required');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
  select * into v_job from public.jobs where id=p_id and farmer_id=v_uid;
  if found and v_job.status not in ('draft','pending') then
    return jsonb_build_object('ok',false,'reason','conflict','row',to_jsonb(v_job));
  end if;
  select * into v_job from public.jobs where id=p_id and farmer_id=v_uid for update;
  if found then

    -- job_sync_value_equality_v1: 比較前に同意時刻だけをDB型へ揃える。
    -- 本人・同意・許可列・行ロック・状態検査を通過した行にのみ適用する。
    if p_patch ? 'work_video_consent_at' then
      p_patch := p_patch || jsonb_build_object('work_video_consent_at',
        (p_patch->>'work_video_consent_at')::timestamptz);
    end if;
    if jsonb_typeof(p_expected) = 'object' and p_expected ? 'work_video_consent_at' then
      p_expected := p_expected || jsonb_build_object('work_video_consent_at',
        (p_expected->>'work_video_consent_at')::timestamptz);
    end if;
if v_job.status='draft' and not exists (
      select 1 from jsonb_each(p_patch) p
      where (to_jsonb(v_job)->p.key) is distinct from p.value
    ) then
      return jsonb_build_object('ok',true,'row',to_jsonb(v_job));
    end if;
    select jsonb_object_agg(key,value) into v_current from jsonb_each(to_jsonb(v_job))
      where key = any(v_allowed || array['status']);
    if p_expected is null or v_current is distinct from p_expected then
      return jsonb_build_object('ok',false,'reason','conflict','row',to_jsonb(v_job));
    end if;
    select string_agg(format('%I',k),',' order by k), string_agg(format('r.%I',k),',' order by k)
      into v_columns,v_values from jsonb_object_keys(p_patch) k;
    execute format('update public.jobs set (%s)=(select %s from jsonb_populate_record(null::public.jobs,$1) r),status=''draft'' where id=$2 and farmer_id=$3 returning *',v_columns,v_values)
      into v_job using p_patch,p_id,v_uid;
  else
    if p_expected is not null then return jsonb_build_object('ok',false,'reason','conflict','row',null); end if;
    select string_agg(format('%I',k),',' order by k), string_agg(format('r.%I',k),',' order by k)
      into v_columns,v_values from jsonb_object_keys(p_patch) k;
    execute format('insert into public.jobs(id,farmer_id,status,%s) select $1,$2,''draft'',%s from jsonb_populate_record(null::public.jobs,$3) r returning *',v_columns,v_values)
      into v_job using p_id,v_uid,p_patch;
  end if;
  if v_job.id is null then return jsonb_build_object('ok',false,'reason','not_confirmed'); end if;
  return jsonb_build_object('ok',true,'row',to_jsonb(v_job));
end $function$

CREATE OR REPLACE FUNCTION public.save_my_profile_fields(p_table text, p_expected jsonb, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_allowed text[];
  v_columns text;
  v_values text;
  v_set text;
  v_row jsonb;
begin
  if v_uid is null then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_table = 'worker_profiles' then
    v_allowed := array['nickname','residence_city','transport','farm_experience','physical_level','work_mood','learning_pref','work_pattern','interests','languages','self_declared','experience_entries','experienced_tasks','pr','pr_qa','pr_pending','pr_qa_pending'];
  elsif p_table in ('employer_profiles','consignment_profiles') then
    v_allowed := array['nickname','recruiter_name','recruiter_name_kana','recruiter_address','recruiter_zip','recruiter_prefecture','recruiter_city','recruiter_address_detail','recruiter_contact','consultation_contact','labor_insurance_status','has_transport','has_parking','has_commute_allowance','has_bonus','has_raise','has_severance_pay','employer_pays_supplies','accessory_ok','parking_capacity','smoking_policy','smoking_area','interaction_style','teaching_style','chat_style','question_style','owner_comment','intro_path','intro_joy','intro_crops','intro_atmosphere','intro_message','unique_point','always_do','break_style','transport_area','commute_allowance_detail','supplies_cap','raise_detail','bonus_detail','severance_detail','texts_pending','insurance_items','insurance_notes'];
  elsif p_table = 'emergency_contacts' then
    v_allowed := array['name','relation','phone','confirmed_at'];
  else return jsonb_build_object('ok',false,'reason','invalid_table');
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb
     or octet_length(p_patch::text) > 262144 then
    return jsonb_build_object('ok',false,'reason','invalid_patch');
  end if;
  if p_expected is not null and (jsonb_typeof(p_expected) <> 'object' or p_expected = '{}'::jsonb or octet_length(p_expected::text) > 262144) then
    return jsonb_build_object('ok',false,'reason','invalid_expected');
  end if;
  if exists (select 1 from jsonb_object_keys(p_patch) k where not k = any(v_allowed))
     or (p_expected is not null and exists (select 1 from jsonb_object_keys(p_expected) k where not k = any(v_allowed)))
     or (p_expected is not null and exists (select 1 from jsonb_object_keys(p_patch) k where not p_expected ? k)) then
    return jsonb_build_object('ok',false,'reason','invalid_fields');
  end if;
  -- Identifiers come only from the table/column allowlists; all values are bound parameters.
  select string_agg(format('%I',k),',' order by k),
         string_agg(format('r.%I',k),',' order by k),
         string_agg(format('%I = r.%I',k,k),',' order by k)
    into v_columns,v_values,v_set from jsonb_object_keys(p_patch) k;
  if p_expected is null then
    begin
      execute format('insert into public.%I (auth_id,updated_at,%s) select $2,clock_timestamp(),%s from jsonb_populate_record(null::public.%I,$1) r returning to_jsonb(%I.*)',p_table,v_columns,v_values,p_table,p_table)
        into v_row using p_patch,v_uid;
    exception when unique_violation then
      return jsonb_build_object('ok',false,'reason','conflict');
    end;
  else
    execute format('update public.%I t set %s,updated_at=clock_timestamp() from jsonb_populate_record(null::public.%I,$1) r where t.auth_id=$2 and not exists (select 1 from jsonb_each($3) e where (to_jsonb(t)->e.key) is distinct from e.value) returning to_jsonb(t)',p_table,v_set,p_table)
      into v_row using p_patch,v_uid,p_expected;
  end if;
  if v_row is null then return jsonb_build_object('ok',false,'reason','conflict'); end if;
  return jsonb_build_object('ok',true,'row',v_row);
end;
$function$

