CREATE OR REPLACE FUNCTION public.set_my_available_dates(p_application_id uuid, p_dates jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_worker uuid; v_job int; v_status text; v_hired timestamptz;
        v_ds date; v_de date; v_bad int; v_hol int;
begin
  if auth.uid() is null then return json_build_object('ok',false,'reason','not_logged_in'); end if;

  select a.worker_id, a.job_number, a.status, a.terms_confirmed_farmer_at
    into v_worker, v_job, v_status, v_hired
    from public.applications a where a.id = p_application_id;
  if v_worker is null then return json_build_object('ok',false,'reason','not_found'); end if;
  if v_worker <> auth.uid() then return json_build_object('ok',false,'reason','not_yours'); end if;
  if v_status not in ('approved','meeting','interview') then
    return json_build_object('ok',false,'reason','bad_status');
  end if;
  if v_hired is not null then return json_build_object('ok',false,'reason','already_hired'); end if;

  if p_dates is null or jsonb_typeof(p_dates) <> 'array' or jsonb_array_length(p_dates) = 0 then
    return json_build_object('ok',false,'reason','empty');
  end if;

  select j.date_start, coalesce(j.date_end, j.date_start) into v_ds, v_de
    from public.jobs j where j.job_number = v_job;
  if v_ds is null then return json_build_object('ok',false,'reason','no_period'); end if;

  select count(*) into v_bad from jsonb_array_elements_text(p_dates) d
   where d::date < v_ds or d::date > v_de;
  if v_bad > 0 then
    return json_build_object('ok',false,'reason','out_of_range','message','求人の期間外の日が含まれています');
  end if;

  select count(*) into v_hol
    from jsonb_array_elements_text(p_dates) d
   where d in (select h from public.jobs j,
                 lateral jsonb_array_elements_text(
                   case when jsonb_typeof(j.holidays)='array' then j.holidays else '[]'::jsonb end) h
                where j.job_number = v_job);
  if v_hol > 0 then
    return json_build_object('ok',false,'reason','holiday','message','休日の日が含まれています');
  end if;

  update public.applications
     set available_dates = (select jsonb_agg(distinct d order by d) from jsonb_array_elements_text(p_dates) d)
   where id = p_application_id;

  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.contract_party_name(p_application_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_w uuid; v_f uuid; v_snap jsonb; v_name text; v_other uuid; v_cw timestamptz; v_cf timestamptz;
begin
  select worker_id, farmer_id, terms_snapshot, terms_confirmed_worker_at, terms_confirmed_farmer_at into v_w, v_f, v_snap, v_cw, v_cf
    from public.applications where id = p_application_id;
  if v_w is null then return json_build_object('ok',false,'reason','not_found'); end if;
  if auth.uid() not in (v_w, v_f) then return json_build_object('ok',false,'reason','not_party'); end if;
  if v_snap is null and (v_cw is null or v_cf is null) then
    return json_build_object('ok',false,'reason','not_contracted',
      'message','契約が成立すると、お互いのお名前が表示されます');
  end if;
  v_other := case when auth.uid() = v_f then v_w else v_f end;
  v_name := nullif(btrim(coalesce(
    v_snap #>> array['party_names', case when v_other = v_w then 'worker' else 'farmer' end], '')), '');
  if v_name is null then
    -- 2026-08-02 より前の旧契約は凍結名が存在しないため、従来どおり現在値で代替
    select nullif(btrim(full_name),'') into v_name
      from public.account_holders where auth_id = v_other;
  end if;
  return json_build_object('ok', true, 'name', v_name);
end; $function$

CREATE OR REPLACE FUNCTION private.admin_support_update(p_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_body text, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_previous private.feedback_support_actions%rowtype; v_updated timestamptz;
begin
 if not private.support_is_admin() then raise exception 'SUPPORT_FORBIDDEN'; end if;
 select updated_at into v_updated from public.feedback where id=p_id for update;
 if not found then raise exception 'SUPPORT_NOT_FOUND'; end if;
 select * into v_previous from private.feedback_support_actions where id=p_message_id;
 if found then
   if v_previous.feedback_id<>p_id or v_previous.author_role<>'admin' or v_previous.actor_id is distinct from auth.uid() then raise exception 'SUPPORT_NOT_FOUND'; end if;
   return private.support_detail(p_id,null);
 end if;
 if p_message_id is null or p_status is null or p_status<>all(array['open','checking','answered','resolved']) or length(coalesce(p_body,''))>3000 or (p_status='answered' and nullif(btrim(p_body),'') is null) then raise exception 'SUPPORT_BAD_INPUT'; end if;
 if p_expected_updated_at is null or v_updated<>p_expected_updated_at then raise exception 'SUPPORT_CONFLICT'; end if;
 insert into private.feedback_support_actions(id,feedback_id,author_role,actor_id,body,status) values(p_message_id,p_id,'admin',auth.uid(),nullif(btrim(p_body),''),p_status);
 update public.feedback set status=p_status where id=p_id;
 return private.support_detail(p_id,null);
end $function$

CREATE OR REPLACE FUNCTION public.save_my_consignor_profile(p_owner uuid, p_expected jsonb, p_type text, p_data jsonb, p_expected_phone text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_profile public.consignment_profiles%rowtype;
  v_account public.account_holders%rowtype;
  v_exists boolean;
  v_data jsonb;
  v_phone text := nullif(btrim(p_phone),'');
  v_result jsonb;
begin
  if v_uid is null or v_uid is distinct from p_owner then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_type is null or p_type not in ('individual','corporate') or jsonb_typeof(p_data) is distinct from 'object'
    or octet_length(p_data::text)>262144 or (p_expected is not null and (jsonb_typeof(p_expected) is distinct from 'object'
    or not p_expected ?& array['consignor_type','consignor_data'] or p_expected - array['consignor_type','consignor_data'] <> '{}'::jsonb)) then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  if p_type <> 'individual' and v_phone is not null then return jsonb_build_object('ok',false,'reason','invalid_phone'); end if;
  v_data := p_data - array['ind_name','ind_birth','ind_zip','ind_addr_main','ind_addr_detail','ind_email','ind_phone',
    'corp_name','corp_no','corp_zip','corp_addr_main','corp_addr_detail','corp_phone','corp_email'];
  perform pg_advisory_xact_lock(hashtextextended('consignor:'||v_uid::text,0));
  select * into v_account from public.account_holders where auth_id=v_uid for update;
  if not found then return jsonb_build_object('ok',false,'reason','registration_missing'); end if;
  select * into v_profile from public.consignment_profiles where auth_id=v_uid for update;
  v_exists := found;
  if v_exists and v_profile.consignor_type=p_type and v_profile.consignor_data=v_data
    and (v_phone is null or v_account.contact_phone=v_phone) then
    return jsonb_build_object('ok',true,'profile',to_jsonb(v_profile),'account',to_jsonb(v_account));
  end if;
  if (v_exists and (p_expected is null or p_expected is distinct from jsonb_build_object('consignor_type',v_profile.consignor_type,'consignor_data',v_profile.consignor_data)))
    or (not v_exists and p_expected is not null) then
    return jsonb_build_object('ok',false,'reason','conflict');
  end if;
  if v_phone is not null and v_account.contact_phone is distinct from v_phone then
    if nullif(btrim(v_account.contact_phone),'') is not null or v_account.contact_phone is distinct from p_expected_phone then
      return jsonb_build_object('ok',false,'reason','phone_conflict');
    end if;
    v_result := public.update_account_holder_self(jsonb_build_object('contact_phone',v_phone),'consignment_flow')::jsonb;
    if not coalesce((v_result->>'ok')::boolean,false) then raise exception 'CONSIGNOR_PHONE_NOT_SAVED'; end if;
    select * into v_account from public.account_holders where auth_id=v_uid;
    if v_account.contact_phone is distinct from v_phone then raise exception 'CONSIGNOR_PHONE_NOT_CONFIRMED'; end if;
  end if;
  if v_exists then
    update public.consignment_profiles set consignor_type=p_type,consignor_data=v_data,updated_at=clock_timestamp()
      where auth_id=v_uid returning * into v_profile;
  else
    insert into public.consignment_profiles(auth_id,consignor_type,consignor_data) values(v_uid,p_type,v_data) returning * into v_profile;
  end if;
  if v_profile.auth_id is null then raise exception 'CONSIGNOR_PROFILE_NOT_SAVED'; end if;
  return jsonb_build_object('ok',true,'profile',to_jsonb(v_profile),'account',to_jsonb(v_account));
end $function$

CREATE OR REPLACE FUNCTION public.confirm_terms(p_application_id uuid, p_accept_double_booking boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_worker uuid; v_farmer uuid; v_job int; v_both boolean;
        v_first_farmer boolean := false; v_farmer_name text; v_title text;
        v_headcount int; v_hired int; v_filled boolean := false;
        v_closed uuid[] := '{}'; v_ref text; r record;
        v_dup int;
begin
  select worker_id, farmer_id, job_number into v_worker, v_farmer, v_job
    from public.applications where id = p_application_id;
  if v_worker is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;

  if auth.uid() = v_worker then
    return json_build_object('ok', false, 'reason', 'use_worker_confirmation');
  elsif auth.uid() = v_farmer then
    select terms_confirmed_farmer_at is null into v_first_farmer
      from public.applications where id = p_application_id;
    -- ★二重予約の壁（2026-08-06）：初回確定・受諾なしの時だけ調べて拒否。
    --   実働日集合（agreed_dates優先／無ければ範囲・holidays除外）の積が空でなければ重複。
    --   進行中の判定は app_phase（DB側の段階ラベルの唯一のソース・2026-08-07）
    if v_first_farmer and not coalesce(p_accept_double_booking, false) then
      select a2.job_number into v_dup
        from public.applications a2
       where a2.farmer_id = v_farmer and a2.worker_id = v_worker
         and a2.job_number is distinct from v_job
         and public.app_phase(a2) in ('interview','contracted','working')
         and exists (
           select 1
             from public.app_work_dates(p_application_id) d1
             join public.app_work_dates(a2.id) d2 on d1 = d2
         )
       limit 1;
      if v_dup is not null then
        return json_build_object('ok', false, 'reason', 'double_booked', 'dup_job', v_dup);
      end if;
    end if;
    update public.applications set terms_confirmed_farmer_at = coalesce(terms_confirmed_farmer_at, now())
     where id = p_application_id;
  else
    return json_build_object('ok', false, 'reason', 'not_party');
  end if;

  select terms_confirmed_worker_at is not null and terms_confirmed_farmer_at is not null
    into v_both from public.applications where id = p_application_id;
  if v_both then
    update public.applications a
       set terms_snapshot = coalesce(a.terms_snapshot,
         (select to_jsonb(j) - 'lat' - 'lng' from public.jobs j where j.job_number = v_job)
         || jsonb_build_object('snapshot_at', now()))
     where a.id = p_application_id;
  end if;

  if v_first_farmer then
    begin
      select nullif(btrim(ep.nickname), '') into v_farmer_name
        from public.employer_profiles ep where ep.auth_id = v_farmer;
      v_farmer_name := coalesce(v_farmer_name, '農家');
      select nullif(btrim(concat_ws(' ', j.crop, j.task)), '') into v_title
        from public.jobs j where j.job_number = v_job;
      v_title := coalesce(v_title, '求人 #' || v_job);

      insert into public.messages (application_id, sender_id, body)
      values (p_application_id, v_farmer,
        '🎉 採用が決定しました！「' || v_title || '」でよろしくお願いします。当日までの確認は、このチャットで行いましょう。');

      perform public.send_user_email(v_worker,
        '[chitose-bank] 採用が決定しました',
        v_farmer_name || 'さんの求人「' || v_title || '」(#' || v_job || ')に採用されました。' || E'\n\n' ||
        '■ ここからの流れ：' || E'\n' ||
        '作業日までにチャットで最終確認（集合場所・持ち物・時間）→ 当日作業 → 終了後にお互いを評価します。' || E'\n\n' ||
        '▶ チャットを開く：https://chitose-bank.com/#/chat/' || p_application_id);
    exception when others then null; end;
  end if;

  if v_first_farmer then
    select j.headcount into v_headcount from public.jobs j where j.job_number = v_job;
    select count(*) into v_hired from public.applications a
      where a.job_number = v_job
        and a.terms_confirmed_worker_at is not null
        and a.terms_confirmed_farmer_at is not null;
    if v_headcount is not null and v_headcount > 0 and v_hired >= v_headcount then
      v_filled := true;
      -- ★満員＝募集の終了（2026-08-16たきと指示）。行は残す＝さがすには「掲載終了（満員）」で並び続け、
      --   応募は apply_to_job が job_not_open で拒否する（見た目の帯だけでなく機構で閉じる）
      update public.jobs set status = 'closed'
       where job_number = v_job and status = 'open';
      v_ref := public.job_ref(v_job, 'worker');
      for r in
        select a.id, a.worker_id from public.applications a
         where a.job_number = v_job
           and a.id <> p_application_id
           and a.status in ('applied','approved','meeting','interview')
           and not (a.terms_confirmed_worker_at is not null and a.terms_confirmed_farmer_at is not null)
      loop
        update public.applications
           set status = 'rejected', decided_at = coalesce(decided_at, now())
         where id = r.id;
        v_closed := v_closed || r.id;
        begin
          insert into public.messages (application_id, sender_id, body)
          values (r.id, v_farmer,
            'この求人は、予定していた人数の採用が決まったため募集を終了しました。' ||
            'ご応募いただいたのに、お力になれずすみません。またの機会によろしくお願いします。');
        exception when others then null; end;
        begin
          insert into public.notifications (farmer_id, type, message)
          values (r.worker_id, 'application_declined',
                  '求人 #' || v_job || '：募集人数に達したため終了しました。今回はご縁がありませんでした');
        exception when others then null; end;
        begin
          perform public.send_user_email(r.worker_id,
            '[chitose-bank] 募集終了のお知らせ：求人 #' || v_job,
            '■ ' || v_ref || E'\n\n' ||
            'この求人は、予定していた採用人数に達したため募集を終了しました。' || E'\n' ||
            '今回はご縁がありませんでした。ご応募いただき、ありがとうございました。' || E'\n\n' ||
            '※ 選考の結果ではなく、募集人数に達したことによる終了です。' || E'\n\n' ||
            '他の求人を見る：https://chitose-bank.com/#/search');
        exception when others then null; end;
      end loop;
    end if;
  end if;

  return (select json_build_object('ok', true,
      'worker_confirmed', terms_confirmed_worker_at is not null,
      'farmer_confirmed', terms_confirmed_farmer_at is not null,
      'filled', v_filled,
      'closed_ids', to_jsonb(v_closed))
    from public.applications where id = p_application_id);
end; $function$

CREATE OR REPLACE FUNCTION public.submit_farmer_review(p_application_id uuid, p_want_again boolean, p_entrust boolean, p_public_comment text, p_private_memo text, p_favorite boolean, p_on_time boolean DEFAULT NULL::boolean, p_as_described boolean DEFAULT NULL::boolean, p_followed_instructions boolean DEFAULT NULL::boolean, p_completed_work boolean DEFAULT NULL::boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v json; v_farmer uuid; v_worker uuid;
begin
  select farmer_id, worker_id into v_farmer, v_worker
    from public.applications where id = p_application_id for update;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if auth.uid() is null or v_farmer is distinct from auth.uid() then return json_build_object('ok', false, 'reason', 'not_yours'); end if;

  -- 古いRPCも、完了・メール・お気に入りの副作用を起こす前に期限を検証する。
  begin
    perform public.assert_review_window(p_application_id);
  exception when sqlstate 'P0001' then
    return json_build_object('ok',false,'reason',sqlerrm);
  end;

  -- 完了処理（評価送信は出勤前提。メール失敗はcomplete_work内で握って続行）
  v := public.complete_work(p_application_id, true);
  if not coalesce((v->>'ok')::boolean, false) then return v; end if;

  insert into public.reviews (application_id, reviewer_id, reviewee_id, direction,
                              want_again, entrust, on_time, as_described,
                              followed_instructions, completed_work,
                              public_comment, private_memo)
  values (p_application_id, v_farmer, v_worker, 'farmer_to_worker',
          p_want_again, p_entrust, p_on_time, p_as_described,
          p_followed_instructions, p_completed_work,
          nullif(trim(coalesce(p_public_comment,'')),''), nullif(trim(coalesce(p_private_memo,'')),''))
  on conflict (application_id, direction) do nothing;

  if p_want_again and p_favorite then
    insert into public.repeat_roster (farmer_id, worker_id, source_application_id, notify)
    values (v_farmer, v_worker, p_application_id, true)
    on conflict (farmer_id, worker_id) do nothing;
  end if;

  return json_build_object('ok', true, 'favorited', (p_want_again and p_favorite));
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_job_publish_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ep public.employer_profiles%rowtype;
  v_min int; v_minutes int; v_break int; v_legal int; v_actual int; v_hourly_eq numeric;
begin
  -- draft→pending/open（掲載申請）または pending/open での直INSERT の時だけ発火。
  -- pending→open（運営承認）では再取得しない＝申請時の内容を維持
  if new.status in ('pending','open') and (tg_op = 'INSERT' or coalesce(old.status,'draft') = 'draft' or (tg_op = 'UPDATE' and old.status = 'open' and coalesce(current_setting('cb.edit_open', true), '') = '1')) then
    select * into v_ep from public.employer_profiles where auth_id = new.farmer_id;
    if coalesce(btrim(v_ep.recruiter_name),'') = '' or coalesce(btrim(v_ep.recruiter_address),'') = ''
       or coalesce(btrim(v_ep.recruiter_contact),'') = '' then
      raise exception '募集主の氏名（名称）・住所・連絡先の入力が必要です（求人広告の法定表示事項）';
    end if;
    -- 受動喫煙の状況（2026-08-07追加）：時間外労働と同じ明示事項ので掲載時必須（空のまま公開させない）
    if coalesce(btrim(v_ep.smoking_policy),'') = '' then
      raise exception '受動喫煙の状況の入力が必要です（雇い手プロフィールの「待遇」ボックスで設定できます）';
    end if;
    if coalesce(btrim(new.address),'') = ''
       or regexp_replace(btrim(new.address), '[0０\s　ー\-－‐番地号の、,.]', '', 'g') = '' then
      raise exception '就業場所（番地まで）の入力が必要です（求人広告の法定表示事項）';
    end if;
    -- 時間外労働（2026-08-03）：有無は必須。「あり」なら目安の時間も必須
    if coalesce(btrim(new.overtime_policy),'') = '' then
      raise exception '時間外労働の有無の入力が必要です（労働条件の明示事項）';
    end if;
    if new.overtime_policy = 'あり' and coalesce(btrim(new.overtime_detail),'') = '' then
      raise exception '時間外労働の目安（どれくらいの時間か）の入力が必要です（労働条件の明示事項）';
    end if;

    -- ── 賃金の検査（2026-08-06追加）──
    if coalesce(btrim(new.hourly_wage),'') <> '' and btrim(new.hourly_wage) !~ '^[0-9]+$' then
      raise exception '時給は数字のみで入力してください（例：1100）。円・カンマは付けられません';
    end if;
    if coalesce(btrim(new.daily_wage),'') <> '' and btrim(new.daily_wage) !~ '^[0-9]+$' then
      raise exception '日給は数字のみで入力してください（例：9000）。円・カンマは付けられません';
    end if;
    if coalesce(btrim(new.hourly_wage),'') = '' and coalesce(btrim(new.daily_wage),'') = '' then
      raise exception '報酬（時給または日給）の入力が必要です';
    end if;
    select mw.hourly_wage into v_min
      from public.minimum_wages mw
     where mw.prefecture = new.prefecture
       and mw.effective_from <= (now() at time zone 'Asia/Tokyo')::date
     order by mw.effective_from desc limit 1;
    if v_min is null then
      -- 取得できない時は安全側＝掲載を止める（フロントvalidateMinWageのunknownWageと同じ倒し方）
      raise exception '最低賃金を確認できません（都道府県：%）。運営に連絡してください', coalesce(new.prefecture,'未設定');
    end if;
    if coalesce(btrim(new.hourly_wage),'') <> '' and btrim(new.hourly_wage)::int < v_min then
      raise exception '時給%円は、%の最低賃金（時給%円）を下回っています', btrim(new.hourly_wage), new.prefecture, v_min;
    end if;
    if coalesce(btrim(new.daily_wage),'') <> '' then
      v_minutes := public.job_scheduled_minutes(new.work_time);
      if v_minutes is null then
        raise exception '勤務時間（開始〜終了）を確認できません。日給の最低賃金チェックに必要です';
      end if;
      v_break := coalesce((regexp_match(coalesce(new.break_time,''), '(\d+)'))[1]::int, 0);
      v_legal := case when v_minutes > 480 then 60 when v_minutes > 360 then 45 else 0 end;
      v_actual := v_minutes - greatest(v_break, v_legal);
      if v_actual <= 0 then
        raise exception '実働時間が0以下になります（勤務%・休憩%分）。勤務時間か休憩を見直してください',
          coalesce(new.work_time,'未設定'), greatest(v_break, v_legal);
      end if;
      v_hourly_eq := btrim(new.daily_wage)::numeric * 60 / v_actual;
      if v_hourly_eq < v_min then
        raise exception '日給%円は、実働%分（勤務%・休憩%分）で時給換算すると約%円になり、%の最低賃金（時給%円）を下回っています',
          btrim(new.daily_wage), v_actual, coalesce(new.work_time,'未設定'), greatest(v_break, v_legal),
          floor(v_hourly_eq), new.prefecture, v_min;
      end if;
    end if;
    -- ── 賃金の検査ここまで ──

    new.recruiter_name := v_ep.recruiter_name;
    new.recruiter_address := v_ep.recruiter_address;
    new.recruiter_contact := v_ep.recruiter_contact;
    new.recruiter_name_kana := v_ep.recruiter_name_kana;  -- 2026-08-03追加（カナは任意＝NULL可）
    -- 待遇の確定：プロフィール項目を土台に、求人固有の上書き（new.perks）を重ねて全キー保存。
    -- 以後プロフィールを変えてもこの求人の待遇は変わらない。
    -- 自由記述3項目は承認済みの列値のみ（texts_pending＝審査中の文は入らない・憲法5条）
    new.perks := jsonb_build_object(
      'has_transport', coalesce(v_ep.has_transport, false),
      'transport_area', coalesce(v_ep.transport_area, ''),
      'has_parking', coalesce(v_ep.has_parking, false),
      'parking_capacity', v_ep.parking_capacity,
      'has_commute_allowance', coalesce(v_ep.has_commute_allowance, false),
      'commute_allowance_detail', coalesce(v_ep.commute_allowance_detail, ''),
      'has_bonus', coalesce(v_ep.has_bonus, false),
      'has_raise', coalesce(v_ep.has_raise, false),
      'has_severance_pay', coalesce(v_ep.has_severance_pay, false),
      'raise_detail', coalesce(v_ep.raise_detail, ''),
      'bonus_detail', coalesce(v_ep.bonus_detail, ''),
      'severance_detail', coalesce(v_ep.severance_detail, ''),
      'consultation_contact', coalesce(v_ep.consultation_contact, ''),
      'employer_pays_supplies', coalesce(v_ep.employer_pays_supplies, false),
      'supplies_cap', coalesce(v_ep.supplies_cap, ''),
      'accessory_ok', coalesce(v_ep.accessory_ok, false),
      -- 受動喫煙の状況（2026-08-03）：'' は未設定＝表示側で「ー」。
      -- smoking_area は「喫煙場所あり」の時だけ意味を持つ（編集UI側が他の選択では空で保存する）
      'smoking_policy', coalesce(v_ep.smoking_policy, ''),
      'smoking_area', coalesce(v_ep.smoking_area, '')
    ) || coalesce(new.perks, '{}'::jsonb);
    -- 保険の確定：申請時点のプロフィール保険を凍結（空でも {items:[]} を保存＝申請時点で申告なしの記録）
    new.insurance_snapshot := jsonb_build_object(
      'items', coalesce(v_ep.insurance_items, '[]'::jsonb),
      'notes', coalesce(v_ep.insurance_notes, '{}'::jsonb),
      'snapshot_at', now()
    );
    new.profile_snapshot_at := now();
    -- 賃金支払条件の確定（2026-08-02）：現在は全求人固定ポリシー。
    -- フロントから別値が送られても、この3値へ確定する（入力UIは封印中・固定ポリシーの宣言をデータ化）
    new.pay_method := 'cash';
    new.pay_timing := 'same_day_after_work';
    new.wage_closing_rule := 'each_workday';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.save_my_consignor_consent(p_owner uuid, p_version text, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_row public.consignment_profiles%rowtype;
begin
  if v_uid is null or v_uid is distinct from p_owner then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if nullif(btrim(p_version),'') is null or length(p_version)>120 or p_at is null or not isfinite(p_at) then
    return jsonb_build_object('ok',false,'reason','invalid_consent');
  end if;
  insert into public.consignment_profiles(auth_id,consignment_data_consent,consignment_data_consent_at,consignment_data_consent_version,consignment_data_consent_user_id)
    values(v_uid,true,p_at,p_version,v_uid)
    on conflict(auth_id) do update set consignment_data_consent=true,consignment_data_consent_at=p_at,
      consignment_data_consent_version=p_version,consignment_data_consent_user_id=v_uid,updated_at=clock_timestamp()
    returning * into v_row;
  if v_row.auth_id is null then raise exception 'CONSIGNOR_CONSENT_NOT_SAVED'; end if;
  return jsonb_build_object('ok',true,'profile',to_jsonb(v_row));
end $function$

CREATE OR REPLACE FUNCTION private.save_consignment_bundle(p_owner uuid, p_request_id uuid, p_deal_id uuid, p_expected jsonb, p_patch jsonb, p_expected_field jsonb, p_terms jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_deal public.consignment_deals%rowtype;
  v_field public.consignment_fields%rowtype;
  v_profile public.consignment_profiles%rowtype;
  v_previous private.consignment_save_requests%rowtype;
  v_request jsonb;
  v_result jsonb;
  v_base jsonb;
  v_data jsonb;
  v_name text;
  v_area text;
  v_key text;
  v_value text;
  v_found boolean;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if not exists(select 1 from public.app_admins where auth_id=v_uid) then return jsonb_build_object('ok',false,'reason','forbidden'); end if;
  if p_request_id is null or p_deal_id is null
    or jsonb_typeof(p_patch) is distinct from 'object' or jsonb_typeof(p_terms) is distinct from 'object'
    or jsonb_typeof(p_patch->'spec') is distinct from 'object'
    or jsonb_typeof(p_patch->'status') is distinct from 'string'
    or p_patch->>'status' not in ('draft','agreed','working','inspected','paid','done')
    or not (p_patch ?& array['spec','status','notes']) or p_patch - array['spec','status','notes'] <> '{}'::jsonb
    or (p_patch->'notes' <> 'null'::jsonb and jsonb_typeof(p_patch->'notes') is distinct from 'string')
    or octet_length(p_patch::text)>524288 or octet_length(p_terms::text)>32768
    or p_terms - array['cmn_pay_due','cmn_fee_bearer','cmn_inspect','cmn_cancel'] <> '{}'::jsonb
    or exists(select 1 from jsonb_each(p_terms) where jsonb_typeof(value) is distinct from 'string') then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  if p_expected is not null and (jsonb_typeof(p_expected) is distinct from 'object'
    or not (p_expected ?& array['spec','status','notes','updated_at'])
    or p_expected - array['spec','status','notes','updated_at'] <> '{}'::jsonb) then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  if p_expected_field is not null and (jsonb_typeof(p_expected_field) is distinct from 'object'
    or jsonb_typeof(p_expected_field->'area_a') is distinct from 'string'
    or p_expected_field - 'area_a' <> '{}'::jsonb) then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  if jsonb_typeof(p_patch->'spec'->'photos') is distinct from 'array' then
    return jsonb_build_object('ok',false,'reason','photos_required');
  end if;
  if jsonb_array_length(p_patch->'spec'->'photos')<3 then return jsonb_build_object('ok',false,'reason','photos_required'); end if;
  -- 日時の表記差を正規化。無効日時も変更前に拒否される。
  if p_expected is not null then
    if p_expected->>'updated_at' is null or not isfinite((p_expected->>'updated_at')::timestamptz) then
      return jsonb_build_object('ok',false,'reason','invalid_input');
    end if;
    p_expected := p_expected || jsonb_build_object('updated_at',(p_expected->>'updated_at')::timestamptz);
  end if;
  v_request := jsonb_build_object('deal_id',p_deal_id,'expected',p_expected,'patch',p_patch,'field',p_expected_field,'terms',p_terms);
  perform pg_advisory_xact_lock(hashtextextended('consignment-save:'||p_request_id::text,0));
  select * into v_previous from private.consignment_save_requests where id=p_request_id;
  if found then
    if v_previous.actor_id is distinct from v_uid or v_previous.request is distinct from v_request then
      return jsonb_build_object('ok',false,'reason','request_mismatch');
    end if;
    -- 当時確定した行を返す。他の端末の後続変更を再保存・取り込みしない。
    return v_previous.result;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('consignment-deal:'||p_deal_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('consignor:'||v_uid::text,0));
  select * into v_deal from public.consignment_deals where id=p_deal_id for update;
  v_found := found;
  if v_found then
    v_base := jsonb_build_object('spec',v_deal.spec,'status',v_deal.status,'notes',v_deal.notes,'updated_at',v_deal.updated_at);
    if v_base is distinct from p_expected then return jsonb_build_object('ok',false,'reason','conflict'); end if;
  elsif p_expected is not null then return jsonb_build_object('ok',false,'reason','not_found');
  elsif p_patch->>'status' <> 'draft' then return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  v_name := btrim(coalesce(p_patch->'spec'->>'field_name',''));
  v_area := btrim(coalesce(p_patch->'spec'->>'area_a',''));
  if v_name<>'' then
    select * into v_field from public.consignment_fields where auth_id=v_uid and name=v_name for update;
    if found then
      if v_field.area_a is distinct from v_area and jsonb_build_object('area_a',v_field.area_a) is distinct from p_expected_field then
        return jsonb_build_object('ok',false,'reason','field_conflict');
      end if;
    elsif p_expected_field is not null then return jsonb_build_object('ok',false,'reason','field_conflict'); end if;
  end if;
  select * into v_profile from public.consignment_profiles where auth_id=v_uid for update;
  v_data := coalesce(v_profile.consignor_data,'{}'::jsonb);
  for v_key,v_value in select key,btrim(value #>> '{}') from jsonb_each(p_terms) loop
    if v_value<>'' then
      if btrim(coalesce(v_data->>v_key,''))<>'' and btrim(v_data->>v_key)<>v_value then
        return jsonb_build_object('ok',false,'reason','terms_conflict');
      end if;
      if btrim(coalesce(v_data->>v_key,''))='' then v_data:=jsonb_set(v_data,array[v_key],to_jsonb(v_value)); end if;
    end if;
  end loop;
  begin
    if v_found then
      update public.consignment_deals set spec=p_patch->'spec',status=p_patch->>'status',notes=p_patch->>'notes',updated_at=now()
        where id=p_deal_id returning * into v_deal;
    else
      insert into public.consignment_deals(id,spec,status,notes)
        values(p_deal_id,p_patch->'spec',p_patch->>'status',p_patch->>'notes') returning * into v_deal;
    end if;
    if v_deal.id is null then raise exception 'DEAL_NOT_SAVED'; end if;
    if v_name<>'' then
      if v_field.id is null then
        insert into public.consignment_fields(auth_id,name,region,area_a)
          values(v_uid,v_name,btrim(coalesce(p_patch->'spec'->>'region','')),v_area) returning * into v_field;
      else
        update public.consignment_fields set area_a=v_area,updated_at=now() where id=v_field.id returning * into v_field;
      end if;
      if v_field.id is null then raise exception 'FIELD_NOT_SAVED'; end if;
    end if;
    if v_data is distinct from coalesce(v_profile.consignor_data,'{}'::jsonb) then
      insert into public.consignment_profiles(auth_id,consignor_data) values(v_uid,v_data)
        on conflict(auth_id) do update set consignor_data=excluded.consignor_data,updated_at=now() returning * into v_profile;
      if v_profile.auth_id is null then raise exception 'TERMS_NOT_SAVED'; end if;
    end if;
    v_result:=jsonb_build_object('ok',true,'request_id',p_request_id,'owner',v_uid,'row',to_jsonb(v_deal),
      'field',case when v_field.id is null then null else to_jsonb(v_field) end,
      'profile',case when v_profile.auth_id is null then null else to_jsonb(v_profile) end);
    insert into private.consignment_save_requests(id,actor_id,deal_id,request,result) values(p_request_id,v_uid,p_deal_id,v_request,v_result);
    return v_result;
  exception when others then
    return jsonb_build_object('ok',false,'reason','save_rejected','code',sqlstate);
  end;
end $function$

CREATE OR REPLACE FUNCTION public.trg_reviews_party_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_worker uuid; v_farmer uuid;
begin
  select worker_id, farmer_id into v_worker, v_farmer
    from public.applications where id = new.application_id;
  if v_worker is null then
    raise exception 'レビューの応募が存在しません';
  end if;

  if new.direction = 'farmer_to_worker' then
    if new.reviewer_id <> v_farmer or new.reviewee_id <> v_worker then
      raise exception 'レビューの当事者が応募と一致しません（farmer_to_worker は 農家→働き手のみ）';
    end if;
  elsif new.direction = 'worker_to_farmer' then
    if new.reviewer_id <> v_worker or new.reviewee_id <> v_farmer then
      raise exception 'レビューの当事者が応募と一致しません（worker_to_farmer は 働き手→農家のみ）';
    end if;
  else
    raise exception 'direction が不正です: %', new.direction;
  end if;

  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.trg_firehose()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_on boolean; v_body text; v_total bigint; v_lines text; v_diff jsonb;
  v_redact text[]; v_noise text[] := array['id','updated_at','created_at','auth_id',
    'farmer_id','worker_id','reviewer_id','reviewee_id','application_id',
    'insurance_first_mailed_at','insurance_last_mailed_on','completion_remind_count',
    'pr_hidden_original','pr_submitted_at','lat','lng'];
  v_op text; v_table_jp text; v_actor text; v_is_admin boolean; v_pk text;
begin
  v_redact := case tg_table_name
    when 'messages' then array['body']
    when 'reviews' then array['private_memo']
    when 'account_holders' then array['full_name','postal_code','address','birth_date',
      'contact_email','contact_phone','company_name','company_number']
    else array[]::text[] end;
  v_redact := v_redact || v_noise;

  if tg_op = 'UPDATE' then
    select jsonb_object_agg(n.key, jsonb_build_object('old', o.value, 'new', n.value))
      into v_diff
      from jsonb_each(to_jsonb(new)) n
      join jsonb_each(to_jsonb(old)) o on o.key = n.key
     where n.value is distinct from o.value and not (n.key = any(v_redact));
    if v_diff is null or v_diff = '{}'::jsonb then return new; end if;
  else
    select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_diff
      from jsonb_each(to_jsonb(coalesce(new, old)))
     where not (key = any(v_redact))
       and value is not null and value <> 'null'::jsonb and value #>> '{}' <> '';
  end if;

  begin v_pk := (to_jsonb(coalesce(new, old)) ->> 'id');
  exception when others then v_pk := null; end;

  -- ★監査台帳：管理者含む全操作を無音で記録（メールの手前・除外なし）
  begin
    insert into public.event_audit (actor, table_name, op, row_pk, diff)
    values (auth.uid(), tg_table_name, tg_op, v_pk, v_diff);
  exception when others then null; end;

  -- ★1操作1通の実況メールは廃止（2026-09-25たきと裁定）。
  -- 記録は上の監査台帳だけに残し、public.summarize_user_actions() が
  -- 人ごと・最後の操作から30分たってから、まとめて1通のメールにする。
  -- app_settings.event_firehose='false' でまとめメールも止まる（キルスイッチ）。
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_help_image_reference(p_owner uuid, p_slot text, p_expected jsonb, p_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_before public.help_images%rowtype;
  v_after public.help_images%rowtype;
  v_base jsonb;
  v_count integer;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if not exists(select 1 from public.app_admins where auth_id=v_uid) then return jsonb_build_object('ok',false,'reason','forbidden'); end if;
  if p_slot is null or p_slot !~ '^[a-zA-Z0-9_-]{1,120}$'
    or (p_url is not null and (length(p_url)>2048 or p_url !~ '^https://[^/]+/storage/v1/object/public/help-images/v2/[a-zA-Z0-9_-]+/[0-9a-f-]+\.(jpg|png|webp|gif)$')) then
    return jsonb_build_object('ok',false,'reason','invalid_input');
  end if;
  if p_expected is not null then
    if jsonb_typeof(p_expected) is distinct from 'object' or not (p_expected ?& array['url','updated_at'])
      or p_expected - array['url','updated_at'] <> '{}'::jsonb or jsonb_typeof(p_expected->'url') is distinct from 'string'
      or p_expected->>'updated_at' is null then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
    p_expected := p_expected || jsonb_build_object('updated_at',(p_expected->>'updated_at')::timestamptz);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('help-image:'||p_slot,0));
  select * into v_before from public.help_images where slot_key=p_slot for update;
  if found then
    v_base:=jsonb_build_object('url',v_before.url,'updated_at',v_before.updated_at);
    if v_before.url=p_url then return jsonb_build_object('ok',true,'row',to_jsonb(v_before)); end if;
  elsif p_url is null then return jsonb_build_object('ok',true,'row',null);
  end if;
  if v_base is distinct from p_expected then return jsonb_build_object('ok',false,'reason','conflict'); end if;
  if p_url is null then
    delete from public.help_images where slot_key=p_slot;
    get diagnostics v_count=row_count;
    if v_count<>1 then raise exception 'HELP_IMAGE_DELETE_NOT_CONFIRMED'; end if;
    return jsonb_build_object('ok',true,'row',null);
  elsif v_before.slot_key is null then
    insert into public.help_images(slot_key,url) values(p_slot,p_url) returning * into v_after;
  else
    update public.help_images set url=p_url,updated_at=greatest(now(),v_before.updated_at+interval '1 microsecond') where slot_key=p_slot returning * into v_after;
  end if;
  if v_after.slot_key is distinct from p_slot or v_after.url is distinct from p_url then raise exception 'HELP_IMAGE_SAVE_NOT_CONFIRMED'; end if;
  return jsonb_build_object('ok',true,'row',to_jsonb(v_after));
end $function$

CREATE OR REPLACE FUNCTION public.trg_pay_incident_on_unpaid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_snap jsonb; v_job int; v_farmer uuid; v_worker uuid;
begin
  if new.direction <> 'worker_to_farmer' or new.pay_status is distinct from 'unpaid' then
    return new;
  end if;
  select a.job_number, a.farmer_id, a.worker_id,
         jsonb_build_object(
           'application', to_jsonb(a),
           'job', (select to_jsonb(j) from public.jobs j where j.job_number = a.job_number),
           'day_records', (select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at), '[]'::jsonb)
                             from public.attendance_events e where e.application_id = a.id),
           'final_review', jsonb_build_object(
             'match_level', new.match_level, 'pay_status', new.pay_status,
             'want_again_choice', new.want_again_choice, 'created_at', new.created_at)
         )
    into v_job, v_farmer, v_worker, v_snap
    from public.applications a where a.id = new.application_id;
  if v_farmer is null then return new; end if;

  insert into public.pay_incidents (application_id, reporter_id, farmer_id, worker_id, job_number, snapshot)
  values (new.application_id, new.reviewer_id, v_farmer, v_worker, v_job, v_snap);

  -- 運営への即時通知（アプリ内＋メール。メール失敗で評価の保存は落とさない）
  perform public.notify_admins('pay_incident',
    '💰未払いの申告：求人 #' || coalesce(v_job::text,'?') || '（申告＝確定ではない。事実確認を）');
  begin
    perform public.send_admin_email(
      '[chitose-bank] 💰未払いの申告：求人 #' || coalesce(v_job::text,'?'),
      '働き手の最終評価で「報酬は約束どおり支払われましたか」に【未払い】の回答がありました。' || E'\n' ||
      'これは申告であって、未払いの確定ではありません。' || E'\n\n' ||
      '・求人・契約・日次の記録・最終回答は申告時点の姿で凍結保存されています' || E'\n' ||
      '・必要に応じて双方へ事実確認をしてください（賃金は労基法24条の中心的義務）' || E'\n\n' ||
      '確認：https://chitose-bank.com/#/admin/reports');
  exception when others then null; end;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.wp_nickname_unique()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_norm text;
begin
  v_norm := public.wp_nickname_norm(new.nickname);
  if v_norm = '' then return new; end if;  -- 空は既定名トリガー(wp_default_nickname)の領分
  if tg_op = 'UPDATE' and v_norm = public.wp_nickname_norm(old.nickname) then
    return new;  -- 変更なしの保存は通す（既存重複の残置＝グランドファーザー）
  end if;
  -- upsertのINSERT試行（既存行あり）でも、自分の行と同名なら変更なし扱いで通す（2026-08-14）
  if tg_op = 'INSERT' and exists (
    select 1 from public.worker_profiles w
     where w.auth_id = new.auth_id
       and public.wp_nickname_norm(w.nickname) = v_norm
  ) then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('wp_nickname:' || v_norm, 0));
  if exists (select 1 from public.worker_profiles w
              where w.auth_id <> new.auth_id
                and public.wp_nickname_norm(w.nickname) = v_norm) then
    raise exception 'このニックネームは既に使われています。別のニックネームにしてください';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.move_job_dates(p_job_number integer, p_new_start date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid; v_job public.jobs%rowtype; v_delta integer; v_today date;
  v_new_end date; v_new_holidays jsonb; v_label text; v_inyear boolean;
  v_wd text[] := array['日','月','火','水','木','金','土'];
begin
  v_uid := auth.uid();
  if v_uid is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  if public.is_account_moderated(v_uid) then
    return json_build_object('ok', false, 'reason', 'account_suspended');
  end if;
  if p_new_start is null then return json_build_object('ok', false, 'reason', 'no_date'); end if;

  select * into v_job from public.jobs where job_number = p_job_number;
  if v_job.job_number is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_job.farmer_id <> v_uid then return json_build_object('ok', false, 'reason', 'not_yours'); end if;
  if v_job.status not in ('draft','pending','open') then
    return json_build_object('ok', false, 'reason', 'bad_status');
  end if;
  if v_job.date_start is null then return json_build_object('ok', false, 'reason', 'no_dates'); end if;

  v_today := (now() at time zone 'Asia/Tokyo')::date;
  if p_new_start < v_today then return json_build_object('ok', false, 'reason', 'past_date'); end if;

  if exists (select 1 from public.applications a
              where a.job_number = p_job_number
                and a.status in ('applied','approved','meeting','interview','contracted','working')) then
    return json_build_object('ok', false, 'reason', 'has_applications');
  end if;

  v_delta := p_new_start - v_job.date_start;
  if v_delta = 0 then return json_build_object('ok', true, 'unchanged', true); end if;
  v_new_end := v_job.date_end + v_delta;  -- date_end that null なら null のまま（単日求人）

  -- 休日も同じ日数ずらす（配列でなければそのまま）
  if v_job.holidays is not null and jsonb_typeof(v_job.holidays) = 'array'
     and jsonb_array_length(v_job.holidays) > 0 then
    select jsonb_agg(to_jsonb(to_char((h)::date + v_delta, 'YYYY-MM-DD')) order by h)
      into v_new_holidays
      from jsonb_array_elements_text(v_job.holidays) h;
  else
    v_new_holidays := v_job.holidays;
  end if;

  -- date_label 再生成＝フロント jobDateLabel と同じ規則（今年なら年を省く・単日はその日だけ・
  -- 同月の期間は終わり側を日だけに）。フロントの形式を変えたらここも合わせること
  v_inyear := extract(year from p_new_start) = extract(year from v_today)
          and extract(year from coalesce(v_new_end, p_new_start)) = extract(year from v_today);
  if v_new_end is null or v_new_end = p_new_start then
    v_label := case when v_inyear then to_char(p_new_start, 'FMMM/FMDD')
                    else to_char(p_new_start, 'YYYY/FMMM/FMDD') end
               || '（' || v_wd[extract(dow from p_new_start)::int + 1] || '）';
  else
    v_label := case when v_inyear then to_char(p_new_start, 'FMMM/FMDD')
                    else to_char(p_new_start, 'YYYY/FMMM/FMDD') end
               || '（' || v_wd[extract(dow from p_new_start)::int + 1] || '） 〜 ';
    if v_inyear and extract(year from p_new_start) = extract(year from v_new_end)
       and extract(month from p_new_start) = extract(month from v_new_end) then
      v_label := v_label || to_char(v_new_end, 'FMDD')
                 || '（' || v_wd[extract(dow from v_new_end)::int + 1] || '）';
    else
      v_label := v_label || case when v_inyear then to_char(v_new_end, 'FMMM/FMDD')
                                 else to_char(v_new_end, 'YYYY/FMMM/FMDD') end
                 || '（' || v_wd[extract(dow from v_new_end)::int + 1] || '）';
    end if;
  end if;

  update public.jobs
     set date_start = p_new_start,
         date_end   = v_new_end,
         holidays   = v_new_holidays,
         date_label = v_label
   where job_number = p_job_number;

  return json_build_object('ok', true, 'date_start', p_new_start, 'date_end', v_new_end,
                           'delta_days', v_delta, 'date_label', v_label);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_profile_fields(p_table text, p_expected jsonb, p_patch jsonb, p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_allowed text[];
  v_columns text;
  v_values text;
  v_set text;
  v_row jsonb;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_table = 'worker_profiles' then
    v_allowed := array['nickname','residence_city','transport','farm_experience','physical_level','work_mood','learning_pref','work_pattern','interests','languages','self_declared','experience_entries','experienced_tasks','pr','pr_qa','pr_pending','pr_qa_pending'];
  elsif p_table in ('employer_profiles','consignment_profiles') then
    v_allowed := array['nickname','recruiter_name','recruiter_name_kana','recruiter_address','recruiter_zip','recruiter_prefecture','recruiter_city','recruiter_address_detail','recruiter_contact','consultation_contact','labor_insurance_status','has_transport','has_parking','has_commute_allowance','has_bonus','has_raise','has_severance_pay','employer_pays_supplies','accessory_ok','parking_capacity','smoking_policy','smoking_area','interaction_style','teaching_style','chat_style','question_style','owner_comment','intro_path','intro_joy','intro_crops','intro_atmosphere','intro_message','unique_point','always_do','break_style','transport_area','commute_allowance_detail','supplies_cap','raise_detail','bonus_detail','severance_detail','texts_pending','insurance_items','insurance_notes'];
  elsif p_table = 'emergency_contacts' then
    v_allowed := array['name','relation','phone','confirmed_at'];
  else return jsonb_build_object('ok',false,'reason','invalid_table');
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb
     or octet_length(p_patch::text) > 262144 then
    return jsonb_build_object('ok',false,'reason','invalid_patch');
  end if;
  if p_expected is not null and (jsonb_typeof(p_expected) <> 'object' or p_expected = '{}'::jsonb or octet_length(p_expected::text) > 262144) then
    return jsonb_build_object('ok',false,'reason','invalid_expected');
  end if;
  if exists (select 1 from jsonb_object_keys(p_patch) k where not k = any(v_allowed))
     or (p_expected is not null and exists (select 1 from jsonb_object_keys(p_expected) k where not k = any(v_allowed)))
     or (p_expected is not null and exists (select 1 from jsonb_object_keys(p_patch) k where not p_expected ? k)) then
    return jsonb_build_object('ok',false,'reason','invalid_fields');
  end if;
  -- Identifiers come only from the table/column allowlists; all values are bound parameters.
  select string_agg(format('%I',k),',' order by k),
         string_agg(format('r.%I',k),',' order by k),
         string_agg(format('%I = r.%I',k,k),',' order by k)
    into v_columns,v_values,v_set from jsonb_object_keys(p_patch) k;
  if p_expected is null then
    begin
      execute format('insert into public.%I (auth_id,updated_at,%s) select $2,clock_timestamp(),%s from jsonb_populate_record(null::public.%I,$1) r returning to_jsonb(%I.*)',p_table,v_columns,v_values,p_table,p_table)
        into v_row using p_patch,v_uid;
    exception when unique_violation then
      return jsonb_build_object('ok',false,'reason','conflict');
    end;
  else
    execute format('update public.%I t set %s,updated_at=clock_timestamp() from jsonb_populate_record(null::public.%I,$1) r where t.auth_id=$2 and not exists (select 1 from jsonb_each($3) e where (to_jsonb(t)->e.key) is distinct from e.value) returning to_jsonb(t)',p_table,v_set,p_table)
      into v_row using p_patch,v_uid,p_expected;
  end if;
  if v_row is null then return jsonb_build_object('ok',false,'reason','conflict'); end if;
  return jsonb_build_object('ok',true,'row',v_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.app_errors_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n int;
begin
  -- session_id が null（直叩き等）は「nullの束」として同じ枠で数える。
  -- is not distinct from は索引を使えないので if で分ける
  if new.session_id is null then
    select count(*) into v_n from public.app_errors
      where session_id is null and created_at > now() - interval '1 minute';
    if v_n >= 20 then return null; end if;
    select count(*) into v_n from public.app_errors
      where session_id is null and created_at > now() - interval '1 day';
    if v_n >= 200 then return null; end if;
  else
    select count(*) into v_n from public.app_errors
      where session_id = new.session_id and created_at > now() - interval '1 minute';
    if v_n >= 20 then return null; end if;
    select count(*) into v_n from public.app_errors
      where session_id = new.session_id and created_at > now() - interval '1 day';
    if v_n >= 200 then return null; end if;
  end if;

  select count(*) into v_n from public.app_errors
    where created_at > now() - interval '1 minute';
  if v_n >= 300 then return null; end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.copy_job_once(p_owner uuid, p_request_id uuid, p_job_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_previous private.job_copy_requests%rowtype;
  v_job public.jobs%rowtype;
  v_result jsonb;
begin
  if v_uid is null or p_owner is distinct from v_uid then return jsonb_build_object('ok',false,'reason','not_logged_in'); end if;
  if p_request_id is null or p_job_number is null then return jsonb_build_object('ok',false,'reason','invalid_input'); end if;
  perform pg_advisory_xact_lock(hashtextextended('job-copy:'||p_request_id::text,0));
  select * into v_previous from private.job_copy_requests where id=p_request_id;
  if found then
    if v_previous.actor_id is distinct from v_uid or v_previous.source_number is distinct from p_job_number then
      return jsonb_build_object('ok',false,'reason','request_mismatch');
    end if;
    select * into v_job from public.jobs where id=v_previous.target_id and farmer_id=v_uid;
    if not found then return jsonb_build_object('ok',false,'reason','copy_deleted','request_id',p_request_id); end if;
    return v_previous.result || jsonb_build_object('job',to_jsonb(v_job),'replayed',true,
      'copy_unchanged',to_jsonb(v_job) is not distinct from v_previous.result->'job');
  end if;
  begin
    -- Existing copy policy, validation and triggers remain the only implementation.
    v_result:=public.copy_job(p_job_number)::jsonb;
    if not coalesce((v_result->>'ok')::boolean,false) then return v_result; end if;
    select * into v_job from public.jobs where id=(v_result->'job'->>'id')::uuid and farmer_id=v_uid;
    if not found then raise exception 'COPY_NOT_CONFIRMED'; end if;
    v_result:=v_result||jsonb_build_object('request_id',p_request_id,'owner',v_uid,'replayed',false,'copy_unchanged',true);
    insert into private.job_copy_requests(id,actor_id,source_number,target_id,result)
      values(p_request_id,v_uid,p_job_number,v_job.id,v_result);
    return v_result;
  exception when others then
    return jsonb_build_object('ok',false,'reason','copy_rejected','code',sqlstate);
  end;
end $function$

CREATE OR REPLACE FUNCTION public.summarize_sessions()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; v_email text; v_traj text; v_stats text;
  v_start timestamptz; v_end timestamptz; v_pages int;
  v_n int; v_parts int; v_chunk int; i int; v_from int; v_to int; v_head text;
begin
  for r in
    select auth_id from public.page_events
     where not summarized
       and exists (select 1 from public.app_admins a where a.auth_id = page_events.auth_id)
     group by auth_id
    having max(ts) < now() - interval '30 minutes'
  loop
    select min(ts), max(ts), count(*) into v_start, v_end, v_pages
      from public.page_events where auth_id = r.auth_id and not summarized;

    select coalesce(string_agg('・' || page_hash || '：' || cnt || '回', E'\n' order by cnt desc), 'なし')
      into v_stats
      from (select page_hash, count(*) as cnt
              from public.page_events
             where auth_id = r.auth_id and not summarized
             group by page_hash having count(*) >= 2) t;

    select email into v_email from auth.users where id = r.auth_id;

    v_n := v_pages;
    v_parts := case when v_n <= 150 then 0
                    else least(5, greatest(1, ceil(v_n / 300.0)::int)) end;

    v_head := '■ 利用者：' || coalesce(v_email,'?') || E'\n' ||
      '■ 滞在：' || to_char(v_start at time zone 'Asia/Tokyo','MM/DD HH24:MI') || '〜' ||
        to_char(v_end at time zone 'Asia/Tokyo','MM/DD HH24:MI') ||
        '（' || (extract(epoch from (v_end - v_start))/60)::int || '分・' || v_pages || 'ページ）' || E'\n' ||
      '■ 最初のページ：' || (select page_hash from public.page_events
           where auth_id = r.auth_id and not summarized order by ts limit 1) || E'\n' ||
      '■ 最後のページ（＝離脱点）：' || (select page_hash from public.page_events
           where auth_id = r.auth_id and not summarized order by ts desc limit 1) || E'\n\n' ||
      '■ 再訪ページ（迷いの候補）：' || E'\n' || v_stats;

    if v_parts = 0 then
      select string_agg(
               to_char(ts at time zone 'Asia/Tokyo','HH24:MI:SS') || '　' || page_hash ||
               coalesce('　（' || dwell_sec || '秒）','　（離脱）'),
               E'\n' order by ts)
        into v_traj
        from (select ts, page_hash,
                     extract(epoch from (lead(ts) over (order by ts) - ts))::int as dwell_sec
                from public.page_events
               where auth_id = r.auth_id and not summarized) s;
      begin
        perform public.send_admin_email(
          '[総括] ' || coalesce(v_email,'?') || '　' || v_pages || 'ページ・' ||
            (extract(epoch from (v_end - v_start))/60)::int || '分',
          v_head || E'\n\n' || '■ 軌跡：' || E'\n' || v_traj);
      exception when others then null; end;
    else
      begin
        perform public.send_admin_email(
          '[総括] ' || coalesce(v_email,'?') || '　' || v_pages || 'ページ・' ||
            (extract(epoch from (v_end - v_start))/60)::int || '分',
          v_head || E'\n\n' || '■ 軌跡：' || v_pages || '行あるため別便で ' || v_parts || '通に分けて送ります。');
      exception when others then null; end;

      v_chunk := ceil(v_n::numeric / v_parts)::int;
      for i in 1..v_parts loop
        v_from := (i - 1) * v_chunk + 1;
        v_to   := least(i * v_chunk, v_n);
        exit when v_from > v_n;
        select string_agg(line, E'\n' order by rn) into v_traj
          from (select rn, line from (
                  select row_number() over (order by ts) as rn,
                         to_char(ts at time zone 'Asia/Tokyo','HH24:MI:SS') || '　' || page_hash ||
                           coalesce('　（' || dwell_sec || '秒）','　（離脱）') as line
                    from (select ts, page_hash,
                                 extract(epoch from (lead(ts) over (order by ts) - ts))::int as dwell_sec
                            from public.page_events
                           where auth_id = r.auth_id and not summarized) s
                ) x
               where x.rn between v_from and v_to) y;
        begin
          perform public.send_admin_email(
            '[軌跡 ' || i || '/' || v_parts || '] ' || coalesce(v_email,'?'),
            '■ 利用者：' || coalesce(v_email,'?') || E'\n' ||
            '■ 軌跡 ' || v_from || '〜' || v_to || '行目（全' || v_n || '行）' || E'\n\n' || coalesce(v_traj,''));
        exception when others then null; end;
      end loop;
    end if;

    update public.page_events set summarized = true
     where auth_id = r.auth_id and not summarized;
  end loop;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_moderate_account(p_auth_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_state text; v_label text;
begin
  if not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  if p_action not in ('suspend','ban','unban') then
    return json_build_object('ok', false, 'reason', 'bad_action');
  end if;
  if exists (select 1 from public.app_admins a where a.auth_id = p_auth_id) then
    return json_build_object('ok', false, 'reason', 'cannot_moderate_admin');
  end if;

  v_state := case p_action when 'suspend' then 'suspended' when 'ban' then 'banned' else 'active' end;

  insert into public.account_moderation (auth_id, state, reason, moderated_by, updated_at)
  values (p_auth_id, v_state, p_reason, auth.uid(), now())
  on conflict (auth_id) do update
    set state = excluded.state, reason = excluded.reason,
        moderated_by = excluded.moderated_by, updated_at = now();

  update auth.users
     set banned_until = case when p_action = 'unban' then null else 'infinity'::timestamptz end
   where id = p_auth_id;

  -- 本人への通知（説明の機会＝理由と申し立て先を必ず伝える）
  v_label := case p_action when 'suspend' then '一時停止' when 'ban' then '停止' else '再開' end;
  begin
    if p_action = 'unban' then
      perform public.send_user_email(p_auth_id,
        '[chitose-bank] アカウントの再開のお知らせ',
        'あなたのアカウントの利用を再開しました。' || E'\n' ||
        'ご協力ありがとうございました。' || E'\n\n' ||
        'https://chitose-bank.com');
    else
      perform public.send_user_email(p_auth_id,
        '[chitose-bank] アカウントの' || v_label || 'について（重要）',
        'あなたのアカウントの利用を' || v_label || 'しました。' || E'\n\n' ||
        '■ 理由：' || E'\n' || coalesce(nullif(p_reason,''), '利用規約に違反する行為が確認されたため') || E'\n\n' ||
        '■ この決定に対する申し立てについて：' || E'\n' ||
        'この決定に心当たりがない場合や、事情の説明を希望する場合は、' || E'\n' ||
        'このメールに返信するか、次の窓口までご連絡ください。' || E'\n' ||
        '内容を確認のうえ、必ずお返事します。' || E'\n' ||
        '窓口：t5fki6643qty@gmail.com' || E'\n\n' ||
        '■ あなたの応募・評価・契約の記録は削除されず、保存されています。');
    end if;
  exception when others then null; end;

  return json_build_object('ok', true, 'state', v_state);
end; $function$

CREATE OR REPLACE FUNCTION public.answer_job_question(p_id uuid, p_answer text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job int; v_asker uuid; v_farmer uuid; v_err text;
begin
  select q.job_number, q.asker_id, j.farmer_id into v_job, v_asker, v_farmer
    from public.job_questions q join public.jobs j on j.job_number = q.job_number
   where q.id = p_id;
  if v_job is null then return json_build_object('ok',false,'reason','not_found'); end if;
  if v_farmer <> auth.uid() then return json_build_object('ok',false,'reason','not_yours'); end if;
  v_err := public.jq_ng_check(p_answer);
  if v_err is not null then return json_build_object('ok',false,'reason','ng','message',v_err); end if;
  update public.job_questions set answer = btrim(p_answer), answered_at = now() where id = p_id;
  insert into public.notifications (farmer_id, type, message)
  values (v_asker, 'job_question_answered', '求人 #' || v_job || '：質問に回答がつきました');
  begin
    perform public.send_user_email(v_asker,
      '[chitose-bank] 質問に回答がつきました：求人 #' || v_job,
      '■ ' || public.job_ref(v_job,'worker') || E'\n\n' ||
      '■ あなたの質問への回答：' || E'\n' || btrim(p_answer) ||
      public.job_link(v_job));
  exception when others then null; end;
  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.approve_application(p_application_id uuid, p_approve boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid; v_farmer uuid; v_worker uuid; v_status text; v_job int; v_new text; v_ref text;
  v_avail jsonb;
  v_link text := 'https://chitose-bank.com/#/profile/worker/approved';
begin
  v_caller := auth.uid();
  if v_caller is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  select farmer_id, worker_id, status, job_number, available_dates
    into v_farmer, v_worker, v_status, v_job, v_avail
    from public.applications where id = p_application_id;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_farmer <> v_caller then return json_build_object('ok', false, 'reason', 'not_your_application'); end if;
  if v_status <> 'applied' then return json_build_object('ok', false, 'reason', 'already_decided', 'status', v_status); end if;

  v_new := case when p_approve then 'approved' else 'rejected' end;
  update public.applications
     set status = v_new, decided_at = now(),
         agreed_dates = case when p_approve and v_avail is not null
                              and jsonb_typeof(v_avail) = 'array'
                             then v_avail else agreed_dates end
   where id = p_application_id;
  v_ref := public.job_ref(v_job,'worker');

  if p_approve then
    insert into public.notifications (farmer_id, type, message)
    values (v_worker, 'application_approved',
            '応募が承認されました：求人 #' || v_job || '　チャットで日程を打ち合わせましょう');
    begin
      perform public.send_user_email(v_worker,
        '[chitose-bank] 応募が承認されました：求人 #' || v_job,
        '■ ' || v_ref || E'\n\n' ||
        '応募が承認されました。' ||
        case when v_avail is not null and jsonb_typeof(v_avail) = 'array' then
          E'\nあなたが応募時に選んだ日程で確定しています：' ||
          (select string_agg(to_char(d::date,'MM/DD'), '・' order by d::date)
             from jsonb_array_elements_text(v_avail) d)
        else '' end || E'\n' ||
        'サイト内のチャットで、集合場所などを打ち合わせましょう。' || E'\n\n' ||
        '承認された応募とチャット：' || v_link || public.job_link(v_job));
    exception when others then null; end;
  else
    insert into public.notifications (farmer_id, type, message)
    values (v_worker, 'application_declined',
            '求人 #' || v_job || '：今回はご縁がありませんでした。他の求人もぜひご覧ください');
    begin
      perform public.send_user_email(v_worker,
        '[chitose-bank] 応募の結果について：求人 #' || v_job,
        '■ ' || v_ref || E'\n\n' ||
        '今回はご縁がありませんでした。ご応募ありがとうございました。' || E'\n\n' ||
        '募集の人数や日程の都合による見送りも多くあります。' || E'\n' ||
        'プロフィールを充実させると、承認されやすくなります。' || E'\n\n' ||
        '他の求人を見る：https://chitose-bank.com/#/search');
    exception when others then null; end;
  end if;
  return json_build_object('ok', true, 'status', v_new);
end; $function$

CREATE OR REPLACE FUNCTION public.apply_to_job(p_job_number integer, p_available_dates jsonb DEFAULT NULL::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_worker_id uuid; v_farmer_id uuid; v_status text; v_app_id uuid;
  v_date_start date; v_date_end date; v_is_period boolean; v_avail jsonb;
begin
  v_worker_id := auth.uid();
  if v_worker_id is null then return json_build_object('ok', false, 'reason', 'not_logged_in'); end if;
  if public.is_account_moderated(v_worker_id) then
    return json_build_object('ok', false, 'reason', 'account_suspended');
  end if;

  select farmer_id, status, date_start, date_end into v_farmer_id, v_status, v_date_start, v_date_end from public.jobs where job_number = p_job_number;
  if v_farmer_id is null then return json_build_object('ok', false, 'reason', 'job_not_found'); end if;
  if v_status <> 'open' then return json_build_object('ok', false, 'reason', 'job_not_open'); end if;
  -- 求人者(農家)が停止・追放中なら、その求人は募集終了として扱う（2026-08-16）
  if public.is_account_moderated(v_farmer_id) then return json_build_object('ok', false, 'reason', 'job_not_open'); end if;
  if v_farmer_id = v_worker_id then return json_build_object('ok', false, 'reason', 'own_job'); end if;

  -- 期間求人（date_end有り・単日でない）は「来られる日」の宣言が必須。単日求人は null で従来どおり
  v_is_period := v_date_end is not null and v_date_end <> v_date_start;
  if v_is_period then
    if p_available_dates is null
       or not (p_available_dates = '"any"'::jsonb
               or (jsonb_typeof(p_available_dates) = 'array' and jsonb_array_length(p_available_dates) > 0)) then
      return json_build_object('ok', false, 'reason', 'dates_required');
    end if;
    v_avail := p_available_dates;
  else
    v_avail := null;
  end if;

  -- ★(a) 自由記述の審査待ち（pr_pending）では応募を止めない。未承認の本文は農家に見えない
  --   （worker_profile_for_farmer が under_review を返す）＝公開はしていない。審査を応募の関所にしない。

  -- 本人情報の登録（18歳確認・規約同意の記録）が無いまま応募を届けない（2026-08-17 段B・段C）
  if not exists (select 1 from public.account_holders h where h.auth_id = v_worker_id) then
    return json_build_object('ok', false, 'reason', 'not_registered');
  end if;

  -- ★(b) プロフィールの条件は is_worker_profile_ready（4項目）1本＝仮応募・昇格と同じ物差し（2026-08-17 段C）
  if exists (select 1 from public.app_settings where key = 'apply_profile_gate' and value = 'true') then
    if not public.is_worker_profile_ready(v_worker_id) then
      return json_build_object('ok', false, 'reason', 'profile_incomplete');
    end if;
  end if;

  insert into public.applications (job_number, worker_id, farmer_id, status, available_dates)
  values (p_job_number, v_worker_id, v_farmer_id, 'applied', v_avail)
  on conflict (job_number, worker_id) where status <> 'canceled' do nothing
  returning id into v_app_id;
  if v_app_id is null then return json_build_object('ok', true, 'already', true); end if;

  begin
    insert into public.messages (application_id, sender_id, body)
    values (v_app_id, v_worker_id, 'あなたの求人に応募しました！プロフィールの確認をお願いします。');
    if exists (select 1 from public.applications a where a.id = v_app_id and a.status = 'approved') then
      insert into public.messages (application_id, sender_id, body)
      values (v_app_id, v_farmer_id, '🌟リピート即決の設定により、応募を自動で承認しました（採用ではありません）。チャットで打ち合わせを進めましょう。');
    end if;
  exception when others then null; end;

  return json_build_object('ok', true, 'application_id', v_app_id);
end; $function$

CREATE OR REPLACE FUNCTION public.ask_job_question(p_job integer, p_question text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_farmer uuid; v_err text; v_id uuid;
begin
  if auth.uid() is null then return json_build_object('ok',false,'reason','not_logged_in'); end if;
  select farmer_id into v_farmer from public.jobs
   where job_number = p_job and status = 'open';
  if v_farmer is null then return json_build_object('ok',false,'reason','not_open'); end if;
  -- 求人者(農家)が停止・追放中なら、その求人は募集終了として扱う（2026-08-16）
  if public.is_account_moderated(v_farmer) then return json_build_object('ok',false,'reason','not_open'); end if;
  if v_farmer = auth.uid() then return json_build_object('ok',false,'reason','own_job'); end if;
  v_err := public.jq_ng_check(p_question);
  if v_err is not null then return json_build_object('ok',false,'reason','ng','message',v_err); end if;
  insert into public.job_questions (job_number, asker_id, question)
  values (p_job, auth.uid(), btrim(p_question)) returning id into v_id;
  insert into public.notifications (farmer_id, type, message)
  values (v_farmer, 'job_question', 'あなたの求人 #' || p_job || ' に質問が届きました');
  begin
    perform public.send_user_email(v_farmer,
      '[chitose-bank] 質問が届きました：あなたの求人 #' || p_job,
      '■ ' || public.job_ref(p_job,'farmer') || E'\n\n' ||
      '■ 質問：' || E'\n' || btrim(p_question) || E'\n\n' ||
      '回答は求人ページの「質問」タブからできます。' || E'\n' ||
      '回答は他の閲覧者にも公開され、同じ質問を減らせます。' ||
      public.job_link(p_job));
  exception when others then null; end;
  return json_build_object('ok', true, 'id', v_id);
end; $function$

CREATE OR REPLACE FUNCTION public.count_job_view(p_job_number integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_farmer uuid;
  v_status text;
  v_salt   text;
  v_key    text;
  v_today  date;
begin
  if p_job_number is null then return; end if;
  -- 未ログインは数えない（ログアウトして自分の求人を増やす道を塞ぐ）
  if auth.uid() is null then return; end if;

  select j.farmer_id, j.status into v_farmer, v_status
    from public.jobs j where j.job_number = p_job_number;
  if v_farmer is null then return; end if;
  -- 公開面に出る求人だけ（下書き・審査中は数えない）
  if v_status not in ('open','closed') then return; end if;
  -- 自分の求人は数えない／運営の見回りも数えない（先例 count_worker_profile_view と同じ規則）
  if auth.uid() = v_farmer then return; end if;
  if exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then return; end if;

  -- 同じアカウント×同じ求人は30日に1回だけ（印が無い時は失敗側に倒す＝数えない）
  select s.value into v_salt from public.app_settings s where s.key = 'job_view_mark_salt';
  if v_salt is null or v_salt = '' then return; end if;
  v_key   := encode(extensions.digest(auth.uid()::text || ':' || p_job_number::text || ':' || v_salt, 'sha256'), 'hex');
  v_today := (now() at time zone 'Asia/Tokyo')::date;

  insert into public.job_view_marks (job_number, viewer_key, seen_on)
       values (p_job_number, v_key, v_today)
  on conflict (job_number, viewer_key) do update
    set seen_on = excluded.seen_on
    where public.job_view_marks.seen_on <= excluded.seen_on - 30;
  -- 印が新しく置かれた／30日を過ぎて置き直された時だけ FOUND＝それ以外は数えない
  if not found then return; end if;

  insert into public.job_view_counts (job_number, view_count, updated_at)
       values (p_job_number, 1, now())
  on conflict (job_number) do update
    set view_count = public.job_view_counts.view_count + 1, updated_at = now();
end $function$

CREATE OR REPLACE FUNCTION public.admin_work_reviews(p_direction text DEFAULT 'worker_to_farmer'::text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_items jsonb;
begin
  if auth.uid() is null or not exists (select 1 from public.app_admins where auth_id = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_admin');
  end if;
  if p_direction is null or p_direction not in ('worker_to_farmer','farmer_to_worker') or p_offset is null or p_offset < 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_input');
  end if;
  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc, t.id desc), '[]'::jsonb) into v_items
  from (
    select r.id, r.application_id, r.direction, r.created_at,
      a.job_number, a.work_completed_at, j.crop, j.task,
      wp.nickname as worker_name, ep.nickname as farmer_name,
      r.as_described, r.instructions_clear, r.safety_care, r.paid_as_posted, r.want_again,
      r.match_level, r.pay_status, r.want_again_choice,
      r.work_outcome, r.traits, r.completed_work, r.followed_instructions, r.entrust, r.on_time
    from public.reviews r
    join public.applications a on a.id = r.application_id
    left join public.jobs j on j.job_number = a.job_number
    left join public.worker_profiles wp on wp.auth_id = a.worker_id
    left join public.employer_profiles ep on ep.auth_id = a.farmer_id
    where r.direction = p_direction and (a.work_completed_at is not null or a.status = 'completed')
    order by r.created_at desc, r.id desc limit 31 offset p_offset
  ) t;
  return jsonb_build_object('ok', true, 'items', v_items - 30, 'has_more', jsonb_array_length(v_items) > 30);
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_job_publish_zscope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lis text;
begin
  if new.status in ('pending','open') and (tg_op = 'INSERT' or coalesce(old.status,'draft') = 'draft') then
    new.place_change_scope := coalesce(nullif(btrim(new.place_change_scope), ''), '変更なし');
    new.task_change_scope  := coalesce(nullif(btrim(new.task_change_scope), ''), '変更なし');
    new.contract_renewal := '更新なし（作業期間の満了で契約は終了します。ふたたび働く場合は、新しい応募と募集主の承認による新しい契約になります）';
    new.retirement_terms := '契約は作業期間の満了により終了します。期間の途中で辞める場合は、できるだけ早く募集主に申し出てください。無断欠勤が続く場合や、安全のための指示に従わないなど、やむを得ない事由がある場合には、募集主は法令に定める手続きに従って契約を解除することがあります。';
    select nullif(btrim(ep.labor_insurance_status), '') into v_lis
      from public.employer_profiles ep where ep.auth_id = new.farmer_id;
    new.labor_insurance_status := v_lis;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.request_job_revision(p_job_number integer, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_farmer uuid; v_status text; v_ref text;
begin
  if not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    return json_build_object('ok', false, 'reason', 'reason_required');
  end if;
  select farmer_id, status into v_farmer, v_status from public.jobs where job_number = p_job_number;
  if v_farmer is null then return json_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_status not in ('pending','open') then
    return json_build_object('ok', false, 'reason', 'not_revisable', 'status', v_status);
  end if;
  v_ref := public.job_ref(p_job_number,'farmer');
  update public.jobs set status = 'draft', revision_requested_at = now() where job_number = p_job_number;
  insert into public.notifications (farmer_id, type, message)
  values (v_farmer, 'job_revision_requested',
          'あなたの求人 #' || p_job_number || ' の修正をお願いします：' || p_reason);
  begin
    perform public.send_user_email(v_farmer,
      '[chitose-bank] あなたの求人 #' || p_job_number || ' の修正のお願い',
      '■ ' || v_ref || E'\n\n' ||
      '確認の結果、以下の点の修正をお願いすることになりました。' || E'\n\n' ||
      '■ 修正をお願いする点：' || E'\n' || p_reason || E'\n\n' ||
      '求人は「作成中」に戻しています。修正のうえ、もう一度掲載してください。' || E'\n' ||
      '（内容の正確な表示のためのお願いであり、採否には一切関与しません）' || E'\n\n' ||
      '▶ この求人の修正はこちら：https://chitose-bank.com/#/work/edit/' || p_job_number);
  exception when others then null; end;
  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.request_profile_revision(p_auth_id uuid, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_pr text; v_nickname text;
begin
  if not exists (select 1 from public.app_admins a where a.auth_id = auth.uid()) then
    return json_build_object('ok', false, 'reason', 'not_admin');
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    return json_build_object('ok', false, 'reason', 'reason_required');
  end if;

  select pr, nickname into v_pr, v_nickname
    from public.worker_profiles where auth_id = p_auth_id;

  update public.worker_profiles
     set pr_hidden_original = coalesce(pr_hidden_original, v_pr),
         pr = null
   where auth_id = p_auth_id;

  insert into public.notifications (farmer_id, type, message)
  values (p_auth_id, 'profile_revision_requested',
          '自己紹介の修正をお願いします：' || p_reason);
  begin
    perform public.send_user_email(p_auth_id,
      '[chitose-bank] 自己紹介の修正のお願い',
      'ご記入いただいた自己紹介について、以下の点の修正をお願いします。' || E'\n\n' ||
      '■ 修正をお願いする点：' || E'\n' || p_reason || E'\n\n' ||
      '現在、自己紹介は一時的に非表示になっています。' || E'\n' ||
      '修正して保存すると、ふたたび表示されます。' || E'\n\n' ||
      '▶ 修正はこちら：https://chitose-bank.com/#/profile/worker/profile');
  exception when others then null; end;

  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.trg_app_review_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_opened timestamptz;
begin
  if tg_op='INSERT' then new.review_opened_at:=null; return new; end if;
  new.review_opened_at:=old.review_opened_at;
  if old.review_opened_at is null and old.status in ('approved','meeting','interview','contracted','working','completed') then
    v_opened:=coalesce(public.app_work_due_at(old.id),old.work_completed_at);
    if v_opened is null and new.status='completed' then v_opened:=new.work_completed_at; end if;
    if v_opened<=clock_timestamp() then new.review_opened_at:=v_opened; end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.set_agreed_dates(p_application_id uuid, p_dates jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_farmer uuid; v_worker uuid; v_job int; v_status text;
        v_ds date; v_de date; v_bad int; v_list text;
begin
  select a.farmer_id, a.worker_id, a.job_number, a.status
    into v_farmer, v_worker, v_job, v_status
    from public.applications a where a.id = p_application_id;
  if v_farmer is null then return json_build_object('ok',false,'reason','not_found'); end if;
  if v_farmer <> auth.uid() then return json_build_object('ok',false,'reason','not_yours'); end if;
  if v_status not in ('approved','meeting','interview','contracted','working') then
    return json_build_object('ok',false,'reason','bad_status');
  end if;
  if p_dates is null or jsonb_typeof(p_dates) <> 'array'
     or jsonb_array_length(p_dates) = 0 then
    return json_build_object('ok',false,'reason','empty');
  end if;

  select j.date_start, coalesce(j.date_end, j.date_start) into v_ds, v_de
    from public.jobs j where j.job_number = v_job;
  select count(*) into v_bad from jsonb_array_elements_text(p_dates) d
   where d::date < v_ds or d::date > v_de;
  if v_bad > 0 then
    return json_build_object('ok',false,'reason','out_of_range',
      'message','求人の期間外の日が含まれています');
  end if;

  update public.applications set agreed_dates = p_dates where id = p_application_id;

  select string_agg(to_char(d::date,'MM/DD'), '・' order by d::date)
    into v_list from jsonb_array_elements_text(p_dates) d;

  insert into public.notifications (farmer_id, type, message)
  values (v_worker, 'dates_agreed',
          '求人 #' || v_job || '：働く日が決まりました（' || v_list || '）');
  begin
    perform public.send_user_email(v_worker,
      '[chitose-bank] 働く日が決まりました：求人 #' || v_job,
      '■ ' || public.job_ref(v_job,'worker') || E'\n\n' ||
      '■ 働く日：' || v_list || E'\n\n' ||
      '内容に相違がないか、確認カードでもう一度ご確認ください。' || E'\n' ||
      '日程の変更が必要になった時は、チャットで相談のうえ、' || E'\n' ||
      '当日の変更は緊急連絡（延期）をお使いください。' || E'\n\n' ||
      'https://chitose-bank.com/#/profile/worker/approved' || public.job_link(v_job));
  exception when others then null; end;
  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.push_payload(p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_app_id uuid; v_sender uuid; v_body text;
  v_worker uuid; v_farmer uuid; v_recipient uuid; v_sender_is_worker boolean;
  v_name text; v_snippet text; v_url text; v_tag text;
begin
  if p_kind = 'message' then
    select application_id, sender_id, body into v_app_id, v_sender, v_body
      from public.messages where id = p_id;
    if v_app_id is null then return null; end if;
    select worker_id, farmer_id into v_worker, v_farmer
      from public.applications where id = v_app_id;
    if v_worker is null then return null; end if;
    v_sender_is_worker := (v_sender = v_worker);
    v_recipient := case when v_sender_is_worker then v_farmer else v_worker end;
    if v_recipient is null then return null; end if;
    -- 名前は「その取引での役割」で解決する（2026-08-03 get_my_calendar_jobs と同じ規則）。
    -- 両方の顔を持つ利用者がいるため、働き手優先で解決すると
    -- 農家として出ている取引で働き手名が出てしまう
    if v_sender_is_worker then
      select nullif(btrim(nickname), '') into v_name
        from public.worker_profiles where auth_id = v_sender;
    else
      select nullif(btrim(nickname), '') into v_name
        from public.employer_profiles where auth_id = v_sender;
    end if;
    if v_name is null then
      -- 退会した利用者は名前を出さない（2026-08-07の名前解決と同じ扱い）
      if exists (select 1 from auth.users u
                  where u.id = v_sender and u.email like 'withdrawn+%@withdrawn.invalid') then
        v_name := '退会した利用者';
      else
        v_name := 'お相手';
      end if;
    end if;
    v_url := '/#/chat/' || v_app_id::text;
    -- まとめ方はスレッドごと＝別のチャットの通知が互いに上書きしない（従来は 'cb-chat' 固定で潰れていた）
    v_tag := 'cb-chat-' || v_app_id::text;
  elsif p_kind = 'admin' then
    select user_id, body into v_recipient, v_body
      from public.admin_messages where id = p_id and from_admin;
    if v_recipient is null then return null; end if;
    v_name := '運営';
    v_url := '/#/chat/admin';
    v_tag := 'cb-dm';
  else
    return null;
  end if;

  -- 本文の冒頭だけ（改行・連続空白は1つに畳んでから40文字＋…）
  v_snippet := btrim(regexp_replace(coalesce(v_body, ''), '\s+', ' ', 'g'));
  if v_snippet = '' then v_snippet := '新しいメッセージが届きました'; end if;
  if length(v_snippet) > 40 then v_snippet := left(v_snippet, 40) || '…'; end if;

  return jsonb_build_object(
    'recipient_id', v_recipient,
    'title', v_name,
    'body', v_snippet,
    'url', v_url,
    'tag', v_tag
  );
end; $function$

CREATE OR REPLACE FUNCTION public.worker_trust_info(p_worker_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_joined timestamptz; v_verified timestamptz;
  v_reviewed int; v_want int; v_completed int; v_hours int;
begin
  if auth.uid() is null or (auth.uid() <> p_worker_id and not exists (
    select 1 from public.applications a
    where a.worker_id = p_worker_id and a.farmer_id = auth.uid()
  )) then
    return json_build_object('ok', false, 'reason', 'not_entitled');
  end if;

  select created_at into v_joined from auth.users where id = p_worker_id;
  select created_at into v_verified from public.account_holders where auth_id = p_worker_id;

  select count(*), count(*) filter (where want_again)
    into v_reviewed, v_want
    from public.reviews
   where reviewee_id = p_worker_id
     and direction = 'farmer_to_worker'
     and want_again is not null
     and public.app_review_published(application_id);

  select count(*) into v_completed
    from public.applications
   where worker_id = p_worker_id and status = 'completed' and attended is distinct from false;

  -- hours = app_accrued_minutes: per-day scheduled minutes x finished work days (2026-08-21).
  -- working accrues day by day / completed is frozen at its completion date. same rule as worker_work_record
  select (coalesce(sum(public.app_accrued_minutes(a.id)), 0) / 60)::int
    into v_hours
    from public.applications a
    join public.jobs j on j.job_number = a.job_number
   where a.worker_id = p_worker_id and a.status in ('working','completed') and a.attended is distinct from false;

  return json_build_object('ok', true, 'joined_at', v_joined, 'verified_at', v_verified,
    'reviewed_count', coalesce(v_reviewed, 0), 'want_again_count', coalesce(v_want, 0),
    'completed_count', coalesce(v_completed, 0), 'total_hours', coalesce(v_hours, 0));
end;
$function$
